NEW_FILES = {'src/language/lector.py': '"""parche-113: LECTOR DE TEXTOS. Aprende de textos largos (articulos, apuntes, paginas copiadas) sin limite de tamaño y sin LLM.\n\nTuberia:  limpiar (citas [5], parentesis, incisos, titulos)  ->  segmentar en frases y clausulas  ->  resolver el TEMA (él/ella/«Es…»/«Su X…»/«Este animal…»)\n          ->  extraer con PATRONES PROPIOS (copulativas, verbales, pasivas, tener, listas, nombres cientificos, fechas)  ->  lo que no se entiende, a la escuela\n          (frases cortas con el sujeto puesto)  ->  informe: hechos aprendidos con su frase de origen, frases no entendidas con el motivo.\nLos patrones funcionan sin la escuela (se pueden medir en cualquier maquina); la escuela solo se usa para lo que ellos no cubren.\nLos hechos se guardan como el resto de la memoria: SUJETO / PREDICADO (verbo_prep) / OBJETO en mayusculas, con su texto para contestar con las mismas palabras."""\nfrom __future__ import annotations\n\nimport json\nimport os\nimport re\nimport unicodedata\nfrom typing import Callable, Dict, List, Optional, Tuple\n\nMAX_TEXTO = 400_000\n_DIR = os.path.dirname(os.path.abspath(__file__))\n\n\ndef nrm(s: str) -> str:\n    return "".join(c for c in unicodedata.normalize("NFD", str(s).lower()) if unicodedata.category(c) != "Mn")\n\n\ndef clave(s: str) -> str:\n    return re.sub(r"_+", "_", re.sub(r"[^A-Z0-9Ñ]+", "_", nrm(s).upper().replace("ñ", "Ñ").replace("n̈", "Ñ"))).strip("_")\n\n\n# ====================================================== léxico y morfología ===============================================================\nclass Lex:\n    """Verbos, adjetivos y sustantivos conocidos (data/lexico_es.json) + conjugaciones generadas. Se carga una vez."""\n    _i = None\n\n    def __init__(self):\n        self.V, self.A, self.N = set(), set(), set()\n        try:\n            d = json.load(open(os.path.join(_DIR, "..", "..", "data", "lexico_es.json"), encoding="utf-8"))\n            for i, l in d.get("syn", {}).items():\n                p = d["pos"].get(i)\n                for w in l:\n                    if " " in w:\n                        continue\n                    w = nrm(w)\n                    (self.V if p == "v" else self.A if p in ("a", "s") else self.N if p == "n" else set()).add(w)\n        except (OSError, ValueError, KeyError):\n            pass\n        self.forma: Dict[str, str] = {}\n        self.part: Dict[str, str] = {}\n        for inf in sorted(self.V | _EXTRA_INF):\n            self._conj(inf)\n        for inf, formas in _IRREG.items():\n            for f in formas.split():\n                self.forma.setdefault(f, inf)\n            self.V.add(inf)\n        for f, inf in _PART_IRREG.items():\n            self.part[f] = inf\n\n    @classmethod\n    def get(cls):\n        if cls._i is None:\n            cls._i = Lex()\n        return cls._i\n\n    def _conj(self, inf: str):\n        if len(inf) < 4 or inf[-2:] not in ("ar", "er", "ir") or " " in inf or inf.endswith("rse"):\n            return\n        st, t = inf[:-2], inf[-2:]\n        vocal = st[-1] in "aeiou"\n        if t == "ar":\n            fs = ["a", "an", "o", "aron", "aba", "aban", "ara", "aran", "aria", "arian"]\n            pa = ["ado", "ada", "ados", "adas"]\n        else:\n            e = "e" if t == "er" else "i"\n            fs = ["e", "en", "io", "ieron", "ia", "ian", e + "ra", e + "ran", e + "ria", e + "rian"]\n            pa = ["ido", "ida", "idos", "idas"]\n            if vocal:\n                fs += ["yo", "yeron"]\n        for f in fs:\n            self.forma.setdefault(st + f, inf)\n        for f in pa:\n            self.part.setdefault(st + f, inf)\n        # alternancias vocalicas del presente (e>ie, o>ue, e>i) y del pret. de los -ir (e>i, o>u)\n        for i in range(len(st) - 1, max(-1, len(st) - 6), -1):\n            if st[i] == "e":\n                self.forma.setdefault(st[:i] + "ie" + st[i + 1:] + "e", inf)\n                self.forma.setdefault(st[:i] + "ie" + st[i + 1:] + "en", inf)\n                self.forma.setdefault(st[:i] + "ie" + st[i + 1:] + "a", inf)\n                self.forma.setdefault(st[:i] + "ie" + st[i + 1:] + "an", inf)\n                if t == "ir":\n                    for f in ("e", "en", "io", "ieron"):\n                        self.forma.setdefault(st[:i] + "i" + st[i + 1:] + f, inf)\n                break\n            if st[i] == "o":\n                for f in (("a", "an") if t == "ar" else ("e", "en")):\n                    self.forma.setdefault(st[:i] + "ue" + st[i + 1:] + f, inf)\n                if t == "ir":\n                    for f in ("io", "ieron"):\n                        self.forma.setdefault(st[:i] + "u" + st[i + 1:] + f, inf)\n                break\n        if st.endswith("c") and t == "er":\n            self.forma.setdefault(st[:-1] + "zca", inf)\n        if st.endswith("c") and t == "ar":\n            self.forma.setdefault(st[:-1] + "quen", inf)\n\n    def lema(self, w: str) -> Optional[str]:\n        w = nrm(w)\n        if w in self.forma:\n            return self.forma[w]\n        if w in _NO_VERBO:\n            return None\n        # forma regular de un verbo que el diccionario no tiene: solo terminaciones muy propias de verbo\n        if len(w) >= 6 and w not in self.N and w not in self.A:\n            for suf, rep in (("aron", "ar"), ("ieron", "er"), ("aban", "ar"), ("ian", "er")):\n                if w.endswith(suf):\n                    return w[:-len(suf)] + rep\n        return None\n\n    def participio(self, w: str) -> Optional[str]:\n        w = nrm(w)\n        if w in self.part:\n            return self.part[w]\n        if len(w) > 4 and re.search(r"(ado|ada|ados|adas)$", w):\n            return re.sub(r"ad[oa]s?$", "ar", w)\n        if len(w) > 4 and re.search(r"(ido|ida|idos|idas)$", w):\n            return re.sub(r"id[oa]s?$", "er", w)\n        return None\n\n    def es_adj(self, w: str) -> bool:\n        w = nrm(w)\n        if w in self.A:\n            return True\n        if w in _NO_ADJ:\n            return False\n        return bool(len(w) > 4 and re.search(r"(oso|osa|osos|osas|ico|ica|icos|icas|ivo|iva|ivos|ivas|able|ibles?|ables|ante|antes|ente|entes|ario|aria|arios|arias|al|ales|ado|ada|ados|adas|ido|ida|idos|idas|ino|ina|inos|inas|udo|uda|ulo|nal|ar|ares|il|iles|eno|ena|enos|enas|ioso|ional)$", w))\n\n\n_EXTRA_INF = set("""vivir habitar encontrar medir pesar alimentar reproducir nacer crecer cazar proteger descubrir describir nombrar llamar considerar crear formar existir\naparecer desconcertar liberar producir pervivir reunir representar poner dar aportar usar utilizar servir emplear fundar gobernar escribir publicar construir\ndirigir morir ocurrir suceder mantener obtener conocer reconocer asignar derivar proceder ayudar generar contener incluir abarcar componer girar orbitar\npoblar extender tener ser estar haber ir hacer poder deber soler""".split())\n_IRREG = {\n    "ser": "es son era eran fue fueron sera seran seria serian sido siendo", "estar": "esta estan estaba estaban estuvo estuvieron estara estaran",\n    "haber": "ha han habia habian hubo habra hay", "ir": "va van iba iban fue fueron ira iran", "tener": "tiene tienen tuvo tuvieron tenia tenian tendra tendran tendria",\n    "hacer": "hace hacen hizo hicieron hacia hacian hara haran", "poder": "puede pueden pudo pudieron podia podian podra podran podria",\n    "poner": "pone ponen puso pusieron ponia ponian pondra", "decir": "dice dicen dijo dijeron decia decian dira", "ver": "ve ven vio vieron veia veian vera",\n    "dar": "da dan dio dieron daba daban dara", "venir": "viene vienen vino vinieron venia venian vendra", "saber": "sabe saben supo supieron sabia sabian sabra",\n    "traer": "trae traen trajo trajeron traia traian", "soler": "suele suelen solia solian", "deber": "debe deben debio debieron debia debian",\n    "caer": "cae caen cayo cayeron caia", "salir": "sale salen salio salieron salia saldra", "conducir": "conduce conducen condujo condujeron", "producir": "produce producen produjo produjeron",\n    "reducir": "reduce reducen redujo", "seguir": "sigue siguen siguio siguieron seguia", "elegir": "elige eligen eligio eligieron", "morir": "muere mueren murio murieron moria",\n    "oir": "oye oyen oyo oyeron", "leer": "lee leen leyo leyeron leia", "creer": "cree creen creyo creyeron creia creian", "huir": "huye huyen huyo",\n    "quedar": "queda quedan quedo quedaron quedaba", "llamar": "llama llaman llamo llamaron llamaba", "ocurrir": "ocurre ocurren ocurrio ocurrieron",\n}\n_PART_IRREG = {"hecho": "hacer", "hecha": "hacer", "hechos": "hacer", "dicho": "decir", "dicha": "decir", "puesto": "poner", "puesta": "poner", "puestos": "poner", "visto": "ver", "vista": "ver", "vistos": "ver",\n               "escrito": "escribir", "escrita": "escribir", "escritos": "escribir", "descrito": "describir", "descrita": "describir", "descritos": "describir", "cubierto": "cubrir", "cubierta": "cubrir",\n               "abierto": "abrir", "abierta": "abrir", "muerto": "morir", "muerta": "morir", "vuelto": "volver", "roto": "romper", "rota": "romper", "sido": "ser", "resuelto": "resolver", "devuelto": "devolver",\n               "descubierto": "descubrir", "descubierta": "descubrir", "descubiertos": "descubrir", "propuesto": "proponer", "compuesto": "componer", "compuesta": "componer", "impreso": "imprimir"}\n_NO_VERBO = set("""forma formas cuenta cuentas nombre nombres cola colas pico picos piel pieles caza centro cargo cambio canto celebra cuerpo duda estado estados fin fines final finales\nhacia sobre entre desde hasta tras para pero sino como cual cuando donde mientras ahora aqui alli mas menos muy casi tambien ademas luego entonces pues mismo misma todo toda\nsentido uso usos papel parte partes dato datos paso pasos caso casos medio medios modo modos lado lados fuera dentro cerca lejos junto""".split())\n_NO_ADJ = set("""mas menos cual cualquier sin sobre entre desde hasta cuando donde nacional animal general especial total central principal""".split()) - {"nacional", "animal", "general", "especial", "total", "central", "principal"}\n\nDET = set("el la los las un una unos unas uno al del lo este esta estos estas ese esa esos esas aquel aquella aquellos aquellas su sus mi mis tu tus nuestro nuestra nuestros nuestras vuestro vuestra otro otra otros otras "\n          "varios varias algun alguna algunos algunas ningun ninguna cada todo toda todos todas mucho mucha muchos muchas poco poca pocos pocas demas ambos ambas cierto cierta ciertos ciertas".split())\nPRE_ADJ = set("unico unica unicos unicas primer primero primera primeros primeras segundo segunda tercer tercero ultimo ultima ultimos ultimas gran grandes principal principales mayor mayores menor menores "\n              "mejor mejores peor mmas menos propio propia propios propias mismo misma mismos mismas nuevo nueva nuevos nuevas viejo antiguo antigua".split())\nNUM = set("dos tres cuatro cinco seis siete ocho nueve diez once doce trece catorce quince veinte treinta cuarenta cincuenta cien ciento mil millon millones".split())\nPREP = set("a ante bajo con contra de del desde durante en entre hacia hasta mediante para por segun sin sobre tras como junto".split())\nADV = set("actualmente ademas tambien asimismo solo solamente incluso casi muy mas menos bastante tan tanto ya aun todavia siempre nunca jamas hoy ahora luego despues antes entonces asi principalmente "\n          "generalmente normalmente habitualmente comunmente aproximadamente aproximada exactamente tipicamente frecuentemente raramente apenas especialmente igualmente finalmente posteriormente originalmente "\n          "recientemente inicialmente probablemente posiblemente realmente efectivamente".split())\nCLASE_ENVOLTURA = {"especie": "ESPECIE", "tipo": "TIPO", "clase": "CLASE", "genero": "GENERO", "forma": "FORMA", "grupo": "GRUPO", "familia": "FAMILIA", "orden": "ORDEN", "subespecie": "SUBESPECIE",\n                   "variedad": "VARIEDAD", "conjunto": "CONJUNTO", "tipos": "TIPO", "clases": "CLASE", "especies": "ESPECIE", "miembro": "MIEMBRO", "ejemplo": "EJEMPLO"}\nTAXON = {"familia", "genero", "orden", "clase", "especie", "subespecie", "reino", "filo", "tribu", "superfamilia", "suborden", "infraorden", "division"}\nABREV = set("sr sra srta dr dra prof lic ing aprox ej etc vs cf pag pags num nº tel fig ed vol cap art av avda cia dpto ee uu a.c d.c s ss pp p.ej e.g i.e".split())\nSUBORD = re.compile(r"^(?:ya que|puesto que|debido a que|porque|aunque|si bien|mientras que|mientras|pero|sin embargo|por lo que|de modo que|de forma que|cuando|donde|como|tras lo cual|llegando|siendo|aunque)\\b", re.I)\nRELATIVO = re.compile(r"^(?:que|quien|quienes|el cual|la cual|los cuales|las cuales|donde|cuyo|cuya|cuyos|cuyas)\\b", re.I)\n\n\n# ====================================================== limpieza y segmentación ===========================================================\nCITAS = re.compile(r"\\[(?:\\d+|nota \\d+|cita requerida|[a-z])\\]|\\[\\d+\\]|\\^\\d+")\n\n\ndef limpiar(texto: str) -> List[Tuple[str, str]]:\n    """-> [("titulo"|"parrafo", texto)]. Quita citas [5], espacios raros, lineas de menu y marcadores."""\n    out = []\n    texto = texto.replace("\\r", "\\n").replace("\xa0", " ").replace("\u200b", "")\n    for linea in texto.split("\\n"):\n        l = CITAS.sub("", linea).strip()\n        l = re.sub(r"\\s+", " ", l)\n        if not l or l.startswith("#") and len(l) < 3 or re.fullmatch(r"[\\W_]+", l):\n            continue\n        l = l.lstrip("#").strip()\n        if len(l.split()) <= 9 and not re.search(r"[.!?:;]$", l) and l[:1].isupper() and not re.search(r"\\b(?:es|son|fue|fueron|era|tiene|tienen)\\b", l):\n            out.append(("titulo", l))\n        else:\n            out.append(("parrafo", l))\n    return out\n\n\ndef _abrev_antes(txt: str, i: int) -> bool:\n    j = i\n    while j > 0 and (txt[j - 1].isalpha() or txt[j - 1] == "."):\n        j -= 1\n    w = txt[j:i].lower().rstrip(".")\n    return w in ABREV or (len(w) == 1 and w.isalpha() and txt[j:i][:1].isupper()) or bool(re.fullmatch(r"(?:[a-z]\\.)+[a-z]", txt[j:i].lower()))\n\n\ndef frases(parrafo: str) -> List[str]:\n    out, ini, n = [], 0, len(parrafo)\n    for m in re.finditer(r"[.!?]+[\\"»”)]*\\s+", parrafo):\n        fin = m.end()\n        sig = parrafo[fin:fin + 1]\n        if not sig or not (sig.isupper() or sig in "¿¡\\"«“—(0123456789"):\n            continue\n        if parrafo[m.start()] == "." and (_abrev_antes(parrafo, m.start()) or re.search(r"\\d$", parrafo[:m.start()]) and sig.isdigit()):\n            continue\n        out.append(parrafo[ini:m.start() + 1].strip())\n        ini = fin\n    if ini < n:\n        out.append(parrafo[ini:].strip())\n    return [f for f in out if len(f.split()) >= 2]\n\n\n# ====================================================== tokens y sintagmas nominales ======================================================\nTOK = re.compile(r"[A-Za-zÁÉÍÓÚÜÑáéíóúüñ0-9][A-Za-zÁÉÍÓÚÜÑáéíóúüñ0-9\'’\\-\\.]*|[,;:()\\"«»—–]")\n\n\nclass W:\n    __slots__ = ("t", "n", "cap", "i")\n\n    def __init__(self, t, i):\n        self.t, self.n, self.i = t.rstrip("."), nrm(t.rstrip(".")), i\n        self.cap = t[:1].isupper() and not t.isupper() or (t.isupper() and len(t) > 1 and t.lower() not in ("xx", "xix", "xviii", "xvii", "xvi", "xv", "xiv", "xiii", "xii", "xi", "x"))\n\n    def __repr__(self):\n        return self.t\n\n\ndef toks(s: str) -> List[W]:\n    out = []\n    for m in TOK.finditer(s):\n        w = m.group()\n        if w.lower() in ("del", "al") and out:\n            out += [W("de" if w.lower() == "del" else "a", len(out)), W("el", len(out) + 1)]\n        else:\n            out.append(W(w, len(out)))\n    return out\n\n\ndef _conector(ws, j) -> bool:\n    """«de» / «el» / «la»… dentro de un nombre propio: «Nueva Gales del Sur» (= de el Sur), «Reino de España»."""\n    n = len(ws)\n    if ws[j].n in ("de", "la", "las", "los", "el"):\n        if j + 1 < n and ws[j + 1].cap:\n            return True\n        if ws[j].n == "de" and j + 2 < n and ws[j + 1].n in ("el", "la", "los", "las") and ws[j + 2].cap:\n            return True\n    return False\n\n\ndef _num_rom(w):\n    return bool(re.fullmatch(r"[ivxlcm]+", w.n)) and w.n not in ("mi", "mil", "vi", "ci", "li", "di", "mix", "vid")\n\n\nclass NP:\n    __slots__ = ("key", "disp", "adjs", "fin", "propio", "head", "nfin", "titulo")\n\n    def __init__(self, key, disp, adjs, fin, propio, head=""):\n        self.key, self.disp, self.adjs, self.fin, self.propio, self.head = key, disp, adjs, fin, propio, head\n\n\ndef np_en(ws: List[W], i: int, lex: Lex, cadena_de=True, inicio_frase=False) -> Optional[NP]:\n    """Sintagma nominal desde ws[i]: (determinante) (numero) nucleo (adjetivos) (de N)*. Los adjetivos se devuelven aparte."""\n    n = len(ws)\n    j = i\n    det_poss = False\n    cuant = ""\n    for qf in CUANTIF:\n        qw = qf.split()\n        if [x.n for x in ws[j:j + len(qw)]] == qw and j + len(qw) < n and (re.fullmatch(r"\\d+(?:[.,]\\d+)?", ws[j + len(qw)].n) or ws[j + len(qw)].n in NUM or ws[j + len(qw)].n in ("unos", "unas")):\n            cuant = " ".join(x.t.lower() for x in ws[j:j + len(qw)])\n            j += len(qw)\n            break\n    while j < n and (ws[j].n in DET or ws[j].n in PRE_ADJ) and not (ws[j].n in NUM and j + 1 < n and ws[j + 1].n in PREP):\n        det_poss = det_poss or ws[j].n in ("su", "sus")\n        j += 1\n        if j < n and ws[j].n == "de" and ws[j - 1].n in ("uno", "una", "unos", "unas", "pocos", "pocas", "muchos", "muchas", "algunos", "algunas", "varios", "varias", "demas", "todos", "todas"):\n            j += 1                                                           # "uno de los pocos mamiferos" -> mamiferos\n            while j < n and (ws[j].n in DET or ws[j].n in PRE_ADJ or ws[j].n in NUM):\n                j += 1\n    if j >= n or ws[j].t in ",;:()\\"«»—–" or ws[j].n in PREP or ws[j].n in ("y", "e", "o", "u", "que", "no", "se", "pero"):\n        return None\n    pal = []\n    propio = False\n    if (ws[j].cap and not (j == 0 and not (j + 1 < n and ws[j + 1].cap))) or (ws[j].cap and j == i and i > 0) or _num_rom(ws[j]) and j > i:\n        propio = True\n    elif j == 0 and ws[j].cap and j + 1 < n and ws[j + 1].cap:\n        propio = True\n    if inicio_frase and j == 0 and ws[0].cap and not (j + 1 < n and ws[j + 1].cap):\n        propio = False\n    start = j\n    if propio:\n        while j < n and (ws[j].cap or _num_rom(ws[j]) or re.fullmatch(r"\\d+", ws[j].n) or _conector(ws, j)):\n            pal.append(ws[j])\n            j += 1\n        head = " ".join(w.t for w in pal)\n    else:\n        if ws[j].n in NUM and j + 1 < n and ws[j + 1].n not in PREP:\n            pal.append(ws[j])\n            j += 1\n        pal.append(ws[j])\n        j += 1\n        head = pal[-1].n\n    if not propio and len(pal) == 1 and pal[0].n in TITULOS:\n        k = j\n        if k < n and ws[k].n == "de" and k + 1 < n and ws[k + 1].cap:\n            k += 1\n        if k < n and ws[k].cap and ws[k].t not in ",;:" and k > 0:\n            nom = []\n            while k < n and (ws[k].cap or _num_rom(ws[k]) or _conector(ws, k)):\n                nom.append(ws[k])\n                k += 1\n            if nom:\n                np2 = NP(clave(re.sub(r"\\bde el\\b", "del", " ".join(w.t for w in nom), flags=re.I)), re.sub(r"\\bde el\\b", "del", " ".join(w.t for w in nom), flags=re.I), [], k, True, clave(nom[0].t))\n                np2.nfin, np2.titulo = k, pal[0].n\n                return np2\n    nuc_fin = j\n    adjs = []\n    comparativo = False\n    while j < n and not propio:\n        w = ws[j]\n        if w.t in ",;:()\\"«»—–" or w.n in PREP or w.n in ("y", "e", "o", "u", "que", "se", "no", "pero") or lex.lema(w.t) and not lex.es_adj(w.t) and w.n not in lex.N:\n            break\n        if w.n in ("mas", "menos") and j + 1 < n and (lex.es_adj(ws[j + 1].t) or ws[j + 1].n in lex.A):\n            j += 2                                                   # comparativo/superlativo: no se guarda como cualidad\n            comparativo = True\n            continue\n        if w.n in ADV:\n            j += 1\n            continue\n        if lex.es_adj(w.t) or (lex.participio(w.t) and w.n not in lex.N):\n            adjs.append(w)\n            j += 1\n            continue\n        if w.n in lex.A or w.n in lex.N and not pal[-1].n.endswith("s") is False:\n            break\n        break\n    # cadena "de/del N" (cola de castor, pico de pato, estado de conservacion)\n    while cadena_de and j + 1 < n and ws[j].n in ("de", "del") and not adjs and not comparativo:\n        k = j + 1\n        sub = np_en(ws, k, lex, cadena_de=True)\n        if sub is None or (not sub.propio and sub.head in {c.upper() for c in CARDINAL}):\n            break\n        pal += [ws[j]] + [w for w in ws[k:sub.nfin] if sub.propio or w.n not in DET or w.n in NUM]\n        j = sub.fin\n        nuc_fin = sub.nfin\n        adjs = list(sub.adjs)\n        if sub.propio:\n            break\n    if not pal:\n        return None\n    conten = list(pal)\n    key = clave(re.sub(r"\\bde el\\b", "del", " ".join(w.t for w in conten), flags=re.I))\n    disp = re.sub(r"\\bde el\\b", "del", " ".join(w.t if (propio and w.cap) else w.t.lower() for w in conten), flags=re.I)\n    if not key:\n        return None\n    if cuant:\n        disp = cuant + " " + disp\n    np_ = NP(key, disp, adjs, j, propio, clave(head))\n    np_.nfin = nuc_fin if not propio else j\n    np_.titulo = ""\n    return np_\n\n\n# ====================================================== extracción por patrones ===========================================================\nclass Hecho(dict):\n    pass\n\n\ndef _h(s, p, o, s_disp, o_disp, tpl="", neg=False, when="", when_disp=""):\n    return Hecho(s=s, p=p, o=o, s_disp=s_disp, o_disp=o_disp, template=tpl, neg=neg, when=when, when_disp=when_disp)\n\n\nclass Tema:\n    """De lo que habla el texto: sustituye a «él», «Es…», «Este animal…», «Su X…»."""\n\n    def __init__(self):\n        self.key = self.disp = None\n        self.propio = False\n        self.clases = set()\n\n    def poner(self, key, disp, propio=False):\n        if key != self.key:\n            self.clases = set()\n        self.key, self.disp, self.propio = key, disp, propio\n\n\ndef _tpl(forma: str, prep: str = "") -> str:\n    return "{s} " + forma.lower() + (" " + prep if prep else "") + " {o}"\n\n\nTITULOS = set("""capitan rey reina doctor doctora profesor profesora general presidente presidenta senor senora san santa don dona principe princesa conde papa emperador sir lord naturalista cientifico\nrevista libro obra periodico familia genero orden clase especie reino tribu filo isla ciudad pais rio monte lago mar oceano estado provincia region condado departamento villa pueblo\npuerto bahia golfo cabo peninsula desierto volcan sierra cordillera valle universidad instituto museo""".split())\nGOBIERNA = set("""endemico nativo originario tipico propio caracteristico parecido cercano proximo lejano similar igual distinto diferente relacionado vinculado perteneciente dependiente famoso conocido capaz\nresponsable sinonimo ajeno comun habitual abundante escaso frecuente rico pobre apto util sensible resistente situado ubicado localizado presente distribuido extendido protegido""".split())\nTEMPORAL = {"ACTUALIDAD", "MOMENTO", "EPOCA", "SIGLO", "ANO", "ANOS", "DIA", "DIAS", "VEZ", "TIEMPO", "PRINCIPIOS", "FINALES", "MEDIADOS", "ANTIGUEDAD", "HISTORIA", "ACTUALMENTE", "VISTA"}\nNUMK = set(NUM) | {"mil", "millones", "millon", "cientos", "docenas", "decenas", "pares", "mitad", "parte", "resto", "total"}\nCARDINAL = {"norte", "sur", "este", "oeste", "noreste", "noroeste", "sureste", "suroeste", "centro", "occidente", "oriente"}\nCUANTIF = ("mas de", "menos de", "unos", "unas", "casi", "cerca de", "alrededor de", "aproximadamente", "mas o menos", "hasta", "al menos")\nUBICAR = {"encontrar", "situar", "ubicar", "localizar", "hallar", "emplazar", "alojar"}\nCLITICO = {"lo", "la", "le", "les", "los", "las", "me", "te", "nos", "os"}\nSTOP_OBJ = {"ELLO", "LO", "LA", "LOS", "LAS", "SI", "QUE", "ESTO", "ESO", "ALGO", "ALGUIEN", "NADA", "CUAL", "COMO", "DONDE", "CUANDO", "SE", "MISMO", "MISMA", "OTRO", "OTRA"}\n\n\n_VERBO_SIN_SUJETO = {"hacer", "existir", "haber", "estudiar", "indicar", "parecer", "importar", "faltar", "bastar"}\n_ADV_BASURA = set("""muy menudo casi tambien aun cualquier juntas rara raras raramente mas menos mucho muchos muchas poco pocos pocas demasiado particularmente practicamente ampliamente aproximadamente\nnumerosas numerosos varios varias diferentes diferente posibles posible siguiente anterior mismo misma mismos mismas otros otras otro otra ciertos ciertas cierto cierta algunos algunas algun alguna\nmientras cuando donde quizas incluso excepto viceversa vez veces tanto tantos tantas todo todos toda todas ambos ambas cada cuantos cuantas cuanto cuanta tal tales asi ademas entonces luego despues antes\nsiempre nunca jamas ya todavia ahora hoy aqui alli alla ahi cerca lejos dentro fuera encima debajo delante detras junto frente casi apenas solamente sencillamente completamente totalmente\naguas nuevamente fieramente frecuentemente generalmente habitualmente normalmente principalmente especialmente actualmente ocasionalmente usualmente supuestamente probablemente posiblemente\nellos ellas ello esto eso aquello nosotros ustedes usted yo tu el ella mi""".split())\n\n\ndef _fin_gerundio(w):\n    return bool(re.search(r"(ando|iendo|yendo)(?:se|lo|la|los|las|le|les|me|te|nos)?$", w))\n\n\ndef _concuerda(s_key, forma, lex=None):\n    """Sujeto omitido: plural<->plural, singular<->singular (solo 3.ª persona)."""\n    f = nrm(forma).split(" ")[0]\n    plural_v = bool(re.search(r"(an|en|on)$", f)) and not re.search(r"(ion|cion)$", f)\n    nuc = nrm(s_key.split("_")[0])\n    plural_s = False\n    if nuc.endswith("s") and len(nuc) > 3 and lex is not None and nuc not in lex.N:\n        cands = [nuc[:-1]] + ([nuc[:-2]] if nuc.endswith("es") else [])\n        plural_s = any(c in lex.N or c in lex.A for c in cands)\n    elif nuc.endswith("s") and len(nuc) > 3 and lex is None:\n        plural_s = not nuc.endswith(("sis", "is", "us"))\n    return plural_s == plural_v\n\n\ndef _FUERTE_VERBO(n):\n    return n.endswith(("aron", "ieron", "aba", "aban", "ia", "ian")) and len(n) > 5\n\n\nTEMPORAL_MIN = {"ano", "anos", "dia", "dias", "mes", "meses", "hora", "horas", "minuto", "minutos", "siglo", "siglos", "milenio", "decada", "semana", "semanas", "periodo", "epoca", "kg", "cm", "km", "mm", "metros", "newtons", "g"}\n_PLURALIA = {"ELLOS", "NUMEROSAS", "ANOS", "DIAS", "PADRES", "HERBAZALES", "ALREDEDORES", "PRESAS_"}\n_SINONIMO_PRED = {"HABITAR": "VIVIR_EN", "HABITAR_EN": "VIVIR_EN", "ALIMENTAR_DE": "COMER", "ALIMENTAR_CON": "COMER", "NUTRIR_DE": "COMER", "ALIMENTAR": "COMER", "RESIDIR_EN": "VIVIR_EN", "MORAR_EN": "VIVIR_EN"}\n\nclass Extractor:\n    def __init__(self, lex: Optional[Lex] = None):\n        self.lex = lex or Lex.get()\n        self.tema = Tema()\n        self.apellido: Dict[str, Tuple[str, str]] = {}\n        self.ultimo = None\n        self.principal = None            # sujeto de la oración principal de la frase anterior (para el sujeto omitido)\n\n    def _recordar(self, np: "NP"):\n        """«George Shaw» ... «Shaw»: la segunda vez es la misma persona."""\n        if np.propio and " " in np.disp and not np.titulo:\n            self.apellido.setdefault(clave(np.disp.split(" ")[-1]), (np.key, np.disp))\n\n    def _resolver(self, np: "NP") -> "NP":\n        if np.propio and " " not in np.disp and np.key in self.apellido:\n            k, d = self.apellido[np.key]\n            np.key, np.disp = k, d\n        else:\n            self._recordar(np)\n        return np\n\n    # ---------- utilidades ----------\n    def _inf(self, w: W) -> bool:\n        n_ = re.sub(r"(?:se|lo|la|le|me|te|nos|los|las)$", "", w.n) if w.n.endswith(("arse", "erse", "irse", "arlo", "arla", "erlo", "irlo")) else w.n\n        return len(n_) > 3 and n_[-2:] in ("ar", "er", "ir") and (n_ in self.lex.V or n_ in _EXTRA_INF or w.n != n_)\n\n    def _verbo(self, ws, i):\n        """-> (fin, lema, forma, negado, es_pasiva, (participio_lema, texto), se) del grupo verbal que empieza en i, o None."""\n        n = len(ws)\n        j, neg, se = i, False, False\n        while j < n and ws[j].n in ("no", "nunca", "jamas", "tampoco", "se", "ya", "tambien", "solo", "incluso", "aun", "todavia", "casi", "actualmente", "aun"):\n            neg = neg or ws[j].n in ("no", "nunca", "jamas", "tampoco")\n            se = se or ws[j].n == "se"\n            j += 1\n        if j >= n:\n            return None\n        lem = self.lex.lema(ws[j].t)\n        if not lem:\n            return None\n        forma = ws[j].t\n        j += 1\n        if lem == "haber" and j < n and (self.lex.participio(ws[j].t) or ws[j].n in _PART_IRREG):\n            lem2 = self.lex.participio(ws[j].t) or _PART_IRREG.get(ws[j].n)\n            return j + 1, lem2, ws[j].t, neg, False, None, se\n        if lem in ("ser", "estar") and j < n:\n            pj = j\n            while pj < n and ws[pj].n in ADV:\n                pj += 1\n            if pj < n:\n                p = self.lex.participio(ws[pj].t) or _PART_IRREG.get(ws[pj].n)\n                if p and ws[pj].n not in DET and ws[pj].n not in lex_noun_adj(self.lex):\n                    return pj + 1, lem, forma, neg, True, (p, ws[pj].t), se\n        if lem in ("poder", "soler", "deber", "tender") and j < n and self._inf(ws[j]):\n            return j + 1, (("poder_" + ws[j].n) if lem == "poder" else ws[j].n), forma + " " + ws[j].t, neg, False, None, se\n        return j, lem, forma, neg, False, None, se\n\n    def _prep_np(self, ws, i):\n        """Complementos desde i: [(prep, NP)] hasta fin de clausula. Reparte «de A y de B» y listas «A, B y C»."""\n        out, n = [], len(ws)\n        j = i\n        prep = ""\n        while j < n:\n            w = ws[j]\n            if w.t in ";()":\n                break\n            if w.t == "," or w.n in ("y", "e", "o", "u"):\n                j += 1\n                if j < n and ws[j].n in ("el", "la", "los", "las", "un", "una", "unos", "unas") and not ws[j].cap:\n                    prep = ""\n                if j < n and ((self.lex.lema(ws[j].t) and not self.lex.es_adj(ws[j].t) and ws[j].n not in self.lex.N) or ws[j].n in ("que", "pero", "cuando", "donde", "como", "porque", "aunque", "si", "ya", "sin")):\n                    break\n                continue\n            if w.n in PREP:\n                if w.n == "como" and j == i:\n                    pass\n                prep = w.n\n                j += 1\n                if j < n and (self._inf(ws[j]) or ws[j].n in ("si", "que")):\n                    break                                              # "para comprobar…", "de dar a luz…": subordinada de infinitivo, no se trocea\n                continue\n            if not prep and j == i and self._inf(ws[j]):\n                break\n            np = np_en(ws, j, self.lex)\n            if np is None:\n                if ws[j].n in ("que", "se", "no", "pero", "como", "si") or self.lex.lema(ws[j].t):\n                    break\n                j += 1\n                continue\n            if np.propio is False and np.key.split("_")[0].lower() in CARDINAL and prep in ("a", "de", "hacia", "desde"):\n                j = np.fin\n                continue\n            if out and out[-1][1].propio is False and "_DE_" in out[-1][1].key and np.propio and ws[j - 1].t in (",", "y", "e"):\n                j = np.fin                                           # «obras de Velázquez, Goya y El Greco»: no se sabe a qué se une la lista\n                continue\n            if prep in ("en", "hasta", "desde", "durante") and re.fullmatch(r"(?:1\\d{3}|20\\d{2})", np.key):\n                out.append(("@cuando", np))\n            else:\n                out.append((prep, np))\n            j = np.fin\n        return out, j\n\n    def _clases(self, np: NP) -> List["Hecho"]:\n        """«la familia Ornithorhynchidae» -> (ORNITHORHYNCHIDAE ES FAMILIA)."""\n        t = getattr(np, "titulo", "")\n        return [_h(np.key, "ES", clave(t), np.disp, t)] if t and np.propio else []\n\n    # ---------- una clausula ----------\n    def clausula(self, texto: str, inicio=False, sujeto=None) -> List["Hecho"]:\n        ws = toks(texto)\n        lex = self.lex\n        while ws and ws[0].n in ("y", "e", "pero", "pues", "ni") or (ws and ws[0].t in ",;"):\n            ws = ws[1:]\n        if len(ws) < 2:\n            return []\n        when = when_disp = ""\n        # adverbial inicial / fecha: "En 1798, ...", "Hasta principios del siglo xx, ...", "Actualmente ..."\n        k = 0\n        if ws[0].n in ("en", "hasta", "desde", "durante", "tras", "hacia", "alrededor", "antes", "despues", "a") or ws[0].n in ADV:\n            for q in range(1, min(len(ws), 12)):\n                if ws[q].t == ",":\n                    k = q + 1\n                    break\n                if lex.lema(ws[q].t) and ws[q].n not in lex.N and not lex.es_adj(ws[q].t) and ws[q].n not in ("siglo",):\n                    break\n            if k == 0 and ws[0].n in ADV:\n                k = 1\n            if k == 0 and ws[0].n == "en" and len(ws) > 3 and re.fullmatch(r"1\\d{3}|20\\d{2}", ws[1].n):\n                k = 2\n            if k:\n                inic = " ".join(w.t for w in ws[:k])\n                my = re.search(r"\\b(1\\d{3}|20\\d{2})\\b", inic)\n                if my and ws[0].n not in ADV:\n                    when, when_disp = my.group(1), inic.strip(" ,").lower()\n                elif ws[0].n not in ADV and ws[0].n in ("hasta", "desde", "durante", "tras", "hacia", "alrededor", "antes", "despues"):\n                    when_disp = ""\n        ws = ws[k:]\n        if len(ws) < 2:\n            return []\n        for q, w in enumerate(ws):\n            w.i = q\n        tema = self.tema\n        # primer verbo conjugado\n        iv = None\n        for q in range(len(ws)):\n            if lex.lema(ws[q].t) and (q == 0 or (ws[q - 1].n not in DET and ws[q - 1].n not in PREP)) and ws[q].n not in _NO_VERBO:\n                if q > 0 and lex.es_adj(ws[q - 1].t) and ws[q].n in lex.N:\n                    continue\n                if q > 0 and ws[q].cap:\n                    continue                                       # «… Asia Occidental»: nombre propio, no «asir»\n                if q > 0 and ws[q].n in lex.A and ws[q - 1].n in lex.N and ws[q - 1].n not in lex.V and ws[q].t != "," and not ws[q].n.endswith(("an", "en", "on")):\n                    continue                                       # «temperatura interna»: adjetivo tras nombre\n                if q > 0 and (ws[q].n in lex.N or ws[q].n in lex.A) and not _FUERTE_VERBO(ws[q].n) and (ws[q - 1].n in ADV or ws[q - 1].n in ("mas", "menos", "tan", "muy") or lex.es_adj(ws[q - 1].t) or ws[q - 1].n in lex.N and q == 1 and False):\n                    continue                                       # «el león más largo»: «largo» no es «largar»\n                iv = q\n                break\n        if iv is None:\n            return []\n        sub_ws = ws[:iv]\n        while sub_ws and sub_ws[-1].n in ("no", "se", "ya", "tambien", "nunca", "solo", "casi", "incluso", "aun", "actualmente"):\n            iv -= 1\n            sub_ws = sub_ws[:-1]\n        if iv + 1 < len(ws) and ws[iv - 1 if iv else 0].n in CLITICO and iv > 0:\n            return []                                              # "… lo convierten en …": sin sujeto fiable\n        if any(w.n in CLITICO for w in sub_ws[-1:]):\n            return []\n        v = self._verbo(ws, iv)\n        if v is None:\n            return []\n        fin_v, lem, forma, neg, pas, part, se = v\n        out: List[Hecho] = []\n        s_key = s_disp = None\n        s_prop = poss = False\n        if sujeto == "PREV":\n            if not self.ultimo:\n                return []\n            s_key, s_disp, s_prop = self.ultimo\n        elif sujeto:\n            s_key, s_disp, s_prop = sujeto\n        elif not sub_ws:\n            s_key, s_disp, s_prop = self.principal if self.principal and not inicio and lem not in ("ser", "estar") else (tema.key, tema.disp, tema.propio)\n        else:\n            np = np_en(sub_ws, 0, lex, cadena_de=True, inicio_frase=inicio)\n            if np is not None:\n                np = self._resolver(np)\n            if np is None:\n                if sub_ws[0].n in ("el", "este", "esta") or all(w.n in ADV or w.n in ("el", "ello") for w in sub_ws):\n                    s_key, s_disp, s_prop = tema.key, tema.disp, tema.propio\n                else:\n                    return []\n            else:\n                resto = sub_ws[np.fin:]\n                if resto and resto[0].t == ",":                               # aposicion: "el capitan John Hunter, segundo gobernador de Nueva Gales del Sur, envio …"\n                    cierre = next((q for q in range(1, len(resto)) if resto[q].t == ","), None)\n                    if cierre is not None and cierre >= 2:\n                        ap = np_en(resto, 1, lex)\n                        if ap is not None:\n                            if np.propio:\n                                out += self._clases(np)\n                                h0 = ap.key\n                                out.append(_h(np.key, "ES", h0.split("_DE_")[0], np.disp, ap.disp.split(" de ")[0]))\n                                if "_DE_" in h0:\n                                    out.append(_h(np.key, h0.split("_DE_")[0] + "_DE", h0.split("_DE_", 1)[1], np.disp, ap.disp.split(" de ", 1)[1], tpl="{s} es " + ap.disp.split(" de ")[0] + " de {o}"))\n                            resto = resto[cierre + 1:]\n                if resto and not all(w.n in ADV or w.t == "," for w in resto):\n                    return []\n                if sub_ws[0].n in ("su", "sus") and tema.key:\n                    s_key, s_disp, poss = tema.key, tema.disp, np\n                elif sub_ws[0].n in ("este", "esta", "estos", "estas", "ese", "esa", "dicho", "dicha") and tema.key and (np.key in tema.clases or _sing(np.key) in tema.clases or np.key in ("ANIMAL", "ESPECIE", "EJEMPLAR", "FELINO", "FELIDO", "MAMIFERO", "PLANTA", "CIUDAD", "PAIS", "PERSONA")):\n                    s_key, s_disp, s_prop = tema.key, tema.disp, tema.propio\n                elif sub_ws[0].n in ("el", "la") and not np.propio and tema.key and np.key in tema.clases:\n                    s_key, s_disp, s_prop = tema.key, tema.disp, tema.propio      # «La ciudad tiene…» = Madrid\n                else:\n                    s_key, s_disp, s_prop = np.key, np.disp, np.propio\n                    out += self._clases(np) if not out else []\n        if not s_key or s_key in STOP_OBJ:\n            return []\n        if not sub_ws and not sujeto and lem in _VERBO_SIN_SUJETO:\n            return []                                              # «hace diez mil años», «existía una interacción»: no es del tema\n        if not sub_ws and not sujeto and not _concuerda(s_key, forma, lex):\n            if tema.key and lem not in ("ser", "estar") and (_concuerda(tema.key, forma, lex) or not tema.propio):\n                s_key, s_disp, s_prop = tema.key, tema.disp, tema.propio\n            else:\n                return []                                          # sujeto omitido: el verbo debe concordar en número con el tema\n        self.ultimo = (s_key, s_disp, s_prop)\n        if sujeto == "PREV":\n            pass\n        # ----- copulativas -----\n        if lem in ("ser", "estar", "parecer", "resultar", "quedar") and not pas:\n            return self._copula(out, ws, fin_v, lem, forma, neg, s_key, s_disp, s_prop, poss, when, when_disp, inicio)\n        if poss:\n            return []                                              # «su X <verbo>…»: sin sujeto claro\n        # ----- pasivas -----\n        if pas and part:\n            inf, ptxt = part\n            comp, _ = self._prep_np(ws, fin_v)\n            cuando = [np for pr, np in comp if pr == "@cuando"]\n            if cuando and not when:\n                when, when_disp = cuando[0].key, "en " + cuando[0].key\n            agente = [np for pr, np in comp if pr == "por"]\n            if agente:\n                for ag in agente[:2]:\n                    out.append(_h(ag.key, clave(inf), s_key, ag.disp, s_disp, tpl=_tpl(_activa(inf)), neg=neg, when=when, when_disp=when_disp))\n                    out += self._clases(ag)\n            elif inf in UBICAR | {"situar"} and any(pr == "en" for pr, _ in comp):\n                pass\n            else:\n                out.append(_h(s_key, "SER", clave(ptxt), s_disp, ptxt.lower(), neg=neg, when=when, when_disp=when_disp))\n            for pr, np in comp[:4]:\n                if re.search(r"(?:^|_)\\d", np.key) or np.key.split("_")[0] in TEMPORAL:\n                    continue\n                if pr == "en" and inf in UBICAR | {"situar"} and np.key not in STOP_OBJ:\n                    out.append(_h(s_key, "ESTAR_EN", np.key, s_disp, np.disp, tpl="{s} está en {o}", neg=neg))\n                    out += self._clases(np)\n                    continue\n                if pr in ("en", "como", "de", "con", "para", "entre", "sobre") and np.key not in STOP_OBJ:\n                    out.append(_h(s_key, clave(ptxt) + "_" + pr.upper(), np.key, s_disp, np.disp, tpl=_tpl("es " + ptxt.lower(), pr), neg=neg, when=when, when_disp=when_disp))\n                    out += self._clases(np)\n            return self._fin(out, s_key, s_disp, s_prop, inicio, False)\n        # ----- verbales -----\n        comp, fin = self._prep_np(ws, fin_v)\n        cuando = [np for pr, np in comp if pr == "@cuando"]\n        if cuando and not when:\n            when, when_disp = cuando[0].key, "en " + cuando[0].key\n        comp = [(pr, np) for pr, np in comp if pr != "@cuando" and np.key not in STOP_OBJ and np.key.split("_")[0] not in TEMPORAL and not re.search(r"(?:^|_)\\d", np.key)]\n        if se and lem in UBICAR and nrm(forma) in ("encuentra", "encuentran", "situa", "ubica", "halla", "localiza", "emplaza", "situan", "ubican", "hallan"):\n            pred0_ = "ESTAR"\n            for pr, np in comp[:2]:\n                if pr == "en":\n                    out.append(_h(s_key, "ESTAR_EN", np.key, s_disp, np.disp, tpl="{s} está en {o}", neg=neg, when=when, when_disp=when_disp))\n                    out += self._clases(np)\n            comp = []\n            if out:\n                return self._fin(out, s_key, s_disp, s_prop, inicio, False)\n        if se and not sub_ws and not sujeto:\n            return []                                                  # "se proyecta una disminucion": impersonal/pasiva refleja sin agente: no se atribuye al tema\n        if lem == "haber" and nrm(forma) == "hay":\n            return []\n        if not comp:\n            return []\n        pred0 = "TENER" if lem == "tener" else clave(lem)\n        if lem == "tener":\n            comp = [(pr, np) for pr, np in comp if not pr]\n        for pr, np in comp[:3]:\n            if pr not in ("", "a", "en", "de", "con", "por", "para", "sobre", "entre", "sin", "contra", "hacia", "desde", "hasta", "como", "ante", "bajo", "durante"):\n                continue\n            if pr in ("hasta", "durante", "desde") and re.search(r"\\b(?:siglo|ano|\\d{3,4})\\b", nrm(np.disp)):\n                continue\n            pred = pred0 + ("_" + pr.upper() if pr and not (lem == "tener" and pr == "") else "")\n            o_key, o_disp = np.key, np.disp\n            if not np.propio and any(w.n in ("su", "sus") for w in ws[fin_v:np.fin]) and s_key:\n                o_key, o_disp = np.key + "_DE_" + s_key, np.disp + " de " + s_disp\n            tpl = "{s} tiene {o}" if lem == "tener" and not pr else _tpl(forma, pr)\n            out.append(_h(s_key, pred, o_key, s_disp, o_disp, tpl=tpl, neg=neg, when=when, when_disp=when_disp))\n            out += self._clases(np)\n            if lem == "tener" and not pr and "_DE_" in np.key and not np.propio and np.key.split("_")[0].lower() not in NUMK:\n                base = np.key.split("_DE_")[0]\n                out.append(_h(s_key, "TENER", base, s_disp, np.disp.split(" de ")[0], tpl="{s} tiene {o}", neg=neg))\n                out.append(_h(np.key, "ES", base, np.disp, np.disp.split(" de ")[0]))\n            for a in np.adjs:\n                if lex.es_adj(a.t):\n                    out.append(_h(o_key, "SER", clave(a.t), o_disp, a.t.lower()))\n        return self._fin(out, s_key, s_disp, s_prop, inicio, False)\n\n    def _copula(self, out, ws, rest_i, lem, forma, neg, s_key, s_disp, s_prop, poss, when, when_disp, inicio):\n        lex = self.lex\n        j = rest_i\n        while j < len(ws) and (ws[j].n in ADV):\n            j += 1\n        if j < len(ws) and ws[j].n in ("cuando", "donde", "como", "porque", "decir", "que", "lo", "cierto", "mas"):\n            return []                                                    # «es cuando el león caza», «es decir…»: no es una definición\n        if j + 1 < len(ws) and ws[j].n in ("el", "la", "lo", "los", "las") and ws[j + 1].n == "de":\n            j += 2                                                       # "su estado de conservacion es el de una especie casi amenazada"\n        # atributo posesivo: (TEMA, ATRIBUTO, valor)\n        def atributo(valor_key, valor_disp):\n            nk = poss.key\n            return [_h(s_key, nk, valor_key, s_disp, valor_disp, tpl="{s} tiene como " + poss.disp + " {o}", neg=neg, when=when, when_disp=when_disp)]\n        # adjetivos directos: "es venenoso", "esta casi amenazada", "es pequeño y ligero"\n        adjs = []\n        q = j\n        while q < len(ws):\n            if ws[q].n in ADV:\n                q += 1\n                continue\n            if ws[q].n in DET or ws[q].n in PREP or not (lex.es_adj(ws[q].t) or lex.participio(ws[q].t)) or (ws[q].n in lex.N and ws[q].n not in lex.A and not lex.participio(ws[q].t)):\n                break\n            adjs.append(ws[q])\n            q += 1\n            if q < len(ws) and (ws[q].n in ("y", "e") or ws[q].t == ","):\n                q += 1\n        if adjs and (q >= len(ws) or ws[q].n in PREP or ws[q].t in ",;"):\n            if poss:\n                return self._fin(atributo(clave(" ".join(a.t for a in adjs)), " ".join(a.t.lower() for a in adjs)), s_key, s_disp, s_prop, inicio, False)\n            for a in adjs:\n                out.append(_h(s_key, "ESTAR" if lem == "estar" else "SER", clave(a.t), s_disp, a.t.lower(), neg=neg, when=when, when_disp=when_disp))\n            a_last = adjs[-1]\n            for pr, np in self._prep_np(ws, q)[0][:3]:\n                if re.search(r"(?:^|_)\\d", np.key) or np.key in STOP_OBJ:\n                    continue\n                if pr == "en" and (self.lex.participio(a_last.t) or "") in UBICAR | {"situar"}:\n                    out = [h for h in out if h["o"] != clave(a_last.t)]\n                    out.append(_h(s_key, "ESTAR_EN", np.key, s_disp, np.disp, tpl="{s} está en {o}", neg=neg))\n                    out += self._clases(np)\n                elif pr in ("de", "en", "a", "con", "por", "para", "como", "entre"):\n                    out.append(_h(s_key, clave(a_last.t) + "_" + pr.upper(), np.key, s_disp, np.disp, tpl="{s} es " + a_last.t.lower() + " " + pr + " {o}", neg=neg))\n                    out += self._clases(np)\n            return self._fin(out, s_key, s_disp, s_prop, inicio, False)\n        np0 = np_en(ws, j, lex, cadena_de=False)\n        if np0 is None:\n            return self._fin(out, s_key, s_disp, s_prop, inicio, False)\n        if poss:\n            vd = (np0.disp + " " + " ".join(a.t.lower() for a in np0.adjs)).strip()\n            return self._fin(atributo(clave(vd), vd), s_key, s_disp, s_prop, inicio, False)\n        partitivo = j + 1 < len(ws) and ws[j].n in ("uno", "una") and ws[j + 1].n == "de"\n        if j < len(ws) and ws[j].n in ("el", "la", "un", "uno", "una") and False:\n            pass\n        # "una especie de mamifero …": la clase es lo que va tras el "de"\n        head_w = None\n        for w in ws[j:np0.nfin]:\n            if w.n not in DET and w.n not in PRE_ADJ and w.n not in NUM:\n                head_w = w\n                break\n        cabeza = head_w.n if head_w else ""\n        tail_i = np0.fin\n        if np0.propio is False and cabeza in CLASE_ENVOLTURA and tail_i + 1 < len(ws) and ws[tail_i].n == "de":\n            sub = np_en(ws, tail_i + 1, lex, cadena_de=True)\n            if sub is not None:\n                out.append(_h(s_key, "ES", sub.key, s_disp, sub.disp, neg=neg, when=when, when_disp=when_disp))\n                out += self._clases(sub)\n                for a in sub.adjs:\n                    out.append(_h(s_key, "SER", clave(a.t), s_disp, a.t.lower(), neg=neg))\n                tail_i = sub.fin\n                gov_adj = sub.adjs[-1] if sub.adjs else None\n                return self._cola(out, ws, tail_i, s_key, s_disp, s_prop, gov_adj, cabeza, "", neg, inicio)\n        # (si no era «especie de X» sigue)\n        if np0.propio:                                                  # "Platypus es un termino", "Madrid es la capital de España" (np0 propio: "X es Y")\n            out.append(_h(s_key, "ES", np0.key, s_disp, np0.disp, neg=neg, when=when, when_disp=when_disp))\n            return self._fin(out, s_key, s_disp, s_prop, inicio, True)\n        if cabeza in CLASE_ENVOLTURA:\n            return self._fin(out, s_key, s_disp, s_prop, inicio, False)        # «es una de las cinco especies»: no dice nada\n        k0, d0 = (_sing(np0.key), _sing(np0.disp)) if partitivo else (np0.key, np0.disp)\n        out.append(_h(s_key, "ES", k0, s_disp, d0, neg=neg, when=when, when_disp=when_disp))\n        for a in np0.adjs:\n            out.append(_h(s_key, "SER", _sing(clave(a.t)) if partitivo else clave(a.t), s_disp, _sing(a.t.lower()) if partitivo else a.t.lower(), neg=neg))\n        gov = np0.adjs[-1] if np0.adjs else None\n        return self._cola(out, ws, tail_i, s_key, s_disp, s_prop, gov, None if partitivo else np0.key, np0.disp, neg, inicio)\n\n    def _cola(self, out, ws, i, s_key, s_disp, s_prop, gov_adj, cabeza_key, cabeza_disp, neg, inicio):\n        """Preposiciones tras la clase: «endémico DE Australia» (lo gobierna el adjetivo) o «representante DE la familia X» (lo gobierna el nombre)."""\n        gob = gov_adj is not None and (nrm(gov_adj.t) in GOBIERNA or self.lex.participio(gov_adj.t))\n        comp, _ = self._prep_np(ws, i)\n        for pr, np in comp[:4]:\n            if pr == "@cuando" or np.key in STOP_OBJ or re.search(r"(?:^|_)\\d", np.key):\n                continue\n            if pr == "":\n                if not np.propio and len(np.key) > 2 and np.key.split("_")[0] not in TEMPORAL:\n                    out.append(_h(s_key, "ES", np.key, s_disp, np.disp))              # «la capital de España Y LA CIUDAD más poblada…»\n                    for a in np.adjs:\n                        out.append(_h(s_key, "SER", clave(a.t), s_disp, a.t.lower()))\n                break                                                              # lo que sigue cuelga de ese segundo sintagma\n            core, cdisp = np.key, np.disp\n            m = re.match(r"(ESTE|OESTE|NORTE|SUR|CENTRO|NORESTE|SURESTE|NOROESTE|SUROESTE)_DE_(.+)", core)\n            if m:\n                core, cdisp = m.group(2), cdisp.split(" de ", 1)[-1]\n            if gob:\n                out.append(_h(s_key, clave(gov_adj.t) + "_" + pr.upper(), core, s_disp, cdisp, tpl="{s} es " + gov_adj.t.lower() + " " + pr + " {o}", neg=neg))\n            elif pr == "de" and cabeza_key and not cabeza_key.startswith("ESPECIE"):\n                h = cabeza_key.split("_DE_")[0]\n                out.append(_h(s_key, h + "_DE", core, s_disp, cdisp, tpl="{s} es " + (cabeza_disp.split(" de ")[0] or h.lower()) + " de {o}", neg=neg))\n            out += self._clases(np)\n        return self._fin(out, s_key, s_disp, s_prop, inicio, True)\n\n    def _fin(self, out, s_key, s_disp, s_prop, inicio, definicion):\n        if definicion and out and (self.tema.key is None or inicio) and not s_key.endswith("_DE_" + (self.tema.key or "#")):\n            self.tema.poner(s_key, s_disp, s_prop)\n        if s_key == self.tema.key:\n            for h in out:\n                if h["s"] == s_key and h["p"] == "ES":\n                    self.tema.clases.add(h["o"])\n        return [h for h in out if h["s"] != h["o"] and h["s"] and h["o"] and h["o"] not in STOP_OBJ and len(h["o"]) > 1]\n\n\ndef lex_noun_adj(lex):\n    return set()\n\n\ndef _sing(w: str) -> str:\n    if not w or " " in w and False:\n        return w\n    return " ".join(_sing1(x) for x in w.split(" ")) if " " in w else _sing1(w)\n\n\ndef _sing1(w: str) -> str:\n    if w.endswith("ces"):\n        return w[:-3] + ("Z" if w.isupper() else "z")\n    if re.search(r"[rlndzjsRLNDZJS][eE][sS]$", w) and not re.search(r"[aeiouAEIOU]ES$|[aeiou]es$", w[-4:-2] + w[-2:]):\n        return w[:-2]\n    return w[:-1] if w.lower().endswith("s") and len(w) > 3 else w\n\n\ndef _activa(lema: str) -> str:\n    l = nrm(lema)\n    if l.endswith("ar"):\n        return l[:-2] + "ó"\n    if l.endswith(("er", "ir")):\n        return l[:-2] + "ió"\n    return l\n\n\n# ====================================================== frase completa ====================================================================\nINCISO = re.compile(r"\\s*[—–]([^—–]{3,200})[—–]\\s*")\nPAREN = re.compile(r"\\s*\\(([^()]{0,120})\\)")\nBINOM = re.compile(r"^[A-Z][a-z]+(?: [a-z]+){1,2}$")\n\n\nclass Lector:\n    """Lee un texto entero y lo guarda en la memoria. `escuela(clausula, tema_disp) -> [dict|Hecho] | None` es opcional (la escuela de español, para lo que los patrones no cubren)."""\n\n    def __init__(self, mem, escuela: Optional[Callable] = None, lex: Optional[Lex] = None):\n        self.mem, self.escuela = mem, escuela\n        self.ex = Extractor(lex)\n        self.vistos: set = set()          # palabras (sin acento) vistas en el texto\n        self.acentos: Dict[str, str] = {}  # sin acento -> con acento, tal como aparece en el texto\n        self.disp_map: Dict[str, str] = {}\n        self.minus: set = set()\n\n    # ---------- control de calidad: mas vale callar que aprender basura ----------\n    def _tok(self, k):\n        return [t for t in nrm(k).split("_") if t]\n\n    def _formas(self, t):\n        fs = [t]\n        if t.endswith("es") and len(t) > 4:\n            fs.append(t[:-2])\n        if t.endswith("s") and len(t) > 3:\n            fs.append(t[:-1])\n            if t.endswith("as"):\n                fs.append(t[:-2] + "o")\n        if t.endswith("a") and len(t) > 3:\n            fs.append(t[:-1] + "o")\n        return fs\n\n    def _solo_adj(self, t):\n        """Adjetivo del diccionario (en cualquier género/número) que no es también nombre."""\n        lex = self.ex.lex\n        fs = self._formas(t)\n        return any(f in lex.A for f in fs) and not any(f in lex.N for f in fs)\n\n    def _malo(self, k, rol, p):\n        """¿Es esta clave un sujeto/objeto inservible? (adverbios, gerundios, infinitivos, numerales, adjetivos sueltos, restos de frase)"""\n        lex = self.ex.lex\n        ts = self._tok(k)\n        if not ts:\n            return True\n        a, z = ts[0], ts[-1]\n        if a in _ADV_BASURA or a in ("ser", "estar", "hace", "hacia", "hay") or z in ("y", "o", "e", "u", "de", "a", "en", "con", "por", "para", "que", "como", "mas", "menos"):\n            return True\n        if re.fullmatch(r"\\d+", a) or a in NUM or a in NUMK or a in TEMPORAL_MIN:\n            return True\n        if _fin_gerundio(a) or a.endswith("mente"):\n            return True\n        if len(ts) == 1:\n            if a in lex.V or (a.endswith(("ar", "er", "ir", "arse", "erse", "irse", "arla", "arlas", "arlo", "arlos", "erla", "erlo")) and self._inf_clitico(a)):\n                if a not in lex.N:\n                    return True                                    # infinitivo suelto\n            if self._solo_adj(a) and not (rol == "o" and (p in ("SER", "ESTAR") or p == "ES" and not a.endswith("s"))):\n                return True                                        # adjetivo suelto como si fuera cosa\n            if lex.lema(a) and a not in lex.N and not lex.es_adj(a) and not k.endswith("_DE"):\n                return True                                        # forma verbal suelta\n        elif len(ts) >= 3 and ts[-2] == "de" and ts[-1] in lex.A and ts[-1] not in lex.N:\n            return True                                            # «cocodrilos_de_considerable»\n        return False\n\n    def _inf_clitico(self, a):\n        lex = self.ex.lex\n        b = re.sub(r"(se|la|las|lo|los|le|les|me|te|nos)$", "", a) if a.endswith(("arse", "erse", "irse", "arla", "arlas", "arlo", "arlos", "erla", "erlo", "irla", "irlo")) else a\n        return b in lex.V\n\n    def _ok(self, h: Hecho) -> bool:\n        lex = self.ex.lex\n        s, p, o = h["s"], h["p"], h["o"]\n        if self._malo(s, "s", p) or self._malo(o, "o", p):\n            return False\n        pp = p.split("_")\n        if pp[0] == "HACER" and len(pp) > 1 or pp[0] in ("PROMEDIAR", "INTERNAR", "SITER", "SITIAR", "SOLER", "SUPONER", "PARECER", "RESULTAR"):\n            return False\n        if pp[0] == "PODER" and (len(pp) > 2 or len(pp) == 1):\n            return False\n        if pp[-1] == "COMO" and len(pp) > 1 and pp[0] not in ("ACTUAR", "FUNCIONAR", "SERVIR", "CONSIDERAR", "USAR", "UTILIZAR", "CONOCER", "LLAMAR", "DESCRIBIR", "CLASIFICAR", "TRABAJAR", "DESEMPENAR", "ACTUA"):\n            return False\n        if pp[0] == "SER" and len(pp) > 1:\n            pass\n        to = self._tok(o)\n        if p == "ES":\n            if len(to) == 1 and to[0] not in lex.N and to[0] not in lex.A and (any(f in lex.part for f in self._formas(to[0])) or lex.lema(to[0])):\n                return False                                       # «es descritas», «es cazando»: forma verbal, no clase\n            if to[0] in ("caso", "hecho", "hizo", "cierto", "capaz", "receptor", "inverso", "igual", "mutuos", "forma", "formas"):\n                return False\n        if p == "SER":\n            if len(to) != 1 or not lex.es_adj(to[0]) and not lex.participio(to[0]):\n                return False\n            if to[0] in lex.N and to[0] not in lex.A and not lex.participio(to[0]):\n                return False\n        if p in ("ESTAR", "ESTAR_EN") and h["o"] == h["s"]:\n            return False\n        return True\n\n    def _singular(self, w, disp):\n        """«leones» -> «león»; solo si la forma singular existe en el léxico (o ya se vio en el texto)."""\n        lex = self.ex.lex\n        n = nrm(w)\n        cands = []\n        if n.endswith("ces"):\n            cands.append(n[:-3] + "z")\n        if n.endswith("es"):\n            cands.append(n[:-2])\n        if n.endswith("s"):\n            cands.append(n[:-1])\n        for c in cands:\n            if len(c) > 2 and (c in lex.N or c in lex.A or c in self.vistos):\n                return c\n        return None\n\n    @staticmethod\n    def _sing_disp(orig, cand):\n        o = (orig or "").lower()\n        for k in (3, 2, 1):\n            if len(o) > k + 1 and nrm(o[:-k]) == cand:\n                return o[:-k]\n            if k == 3 and o.endswith("ces") and nrm(o[:-3] + "z") == cand:\n                return o[:-3] + "z"\n        return None\n\n    def _canon(self, h: Hecho):\n        """Sujeto genérico en plural («los leones viven…») -> el singular de la especie, para que «el león» y «los leones» sean una sola cosa."""\n        s = h["s"]\n        if "_" in s or not s.endswith("S") or len(s) < 5 or nrm(s) not in self.minus:\n            return\n        sg = self._singular(s.lower(), h.get("s_disp") or "")\n        if not sg or sg in ("ser", "estar") or nrm(sg).upper() in _PLURALIA:\n            return\n        sk = clave(sg)\n        h["s"] = sk\n        sd = self.disp_map.get(sk) or self._sing_disp(h.get("s_disp") or "", sg) or (self.acentos.get(sg) or sg)\n        h["s_disp"] = sd[:1].upper() + sd[1:] if (h.get("s_disp") or "")[:1].isupper() else sd\n        if h["p"] in ("ES", "SER") and h["o"] and "_" not in h["o"]:\n            so = self._singular(nrm(h["o"]).lower(), "")\n            if so:\n                h["o"] = clave(so)\n                od = self._sing_disp(h.get("o_disp") or "", so) or self.acentos.get(so) or so\n                h["o_disp"] = od\n        tpl = h.get("template") or ""\n        if tpl:\n            def un(m):\n                v = m.group(2)\n                if v == "son":\n                    nv = "es"\n                elif v.endswith(("an", "en")) and not v.endswith(("ron", "cion", "sion")) and len(v) > 3:\n                    nv = v[:-1]\n                else:\n                    nv = v\n                return m.group(1) + nv\n            h["template"] = re.sub(r"(\\{s\\} (?:no )?)(\\w+)", un, tpl, count=1)\n\n    def _guardar(self, h: Hecho, frase: str, via: str, rep: dict):\n        if h.get("p") in _SINONIMO_PRED:\n            h["p"] = _SINONIMO_PRED[h["p"]]\n        if not self._ok(h):\n            rep["descartados"] = rep.get("descartados", 0) + 1\n            rep.setdefault("lista_descartados", []).append((h["s"], h["p"], h["o"]))\n            return\n        self._canon(h)\n        if not self._ok(h):\n            rep["descartados"] = rep.get("descartados", 0) + 1\n            return\n        if h.get("s_disp"):\n            self.disp_map.setdefault(h["s"], h["s_disp"])\n        tr = (h["s"], h["p"], h["o"])\n        if tr[0] == tr[2] or not all(tr):\n            return\n        nuevo = self.mem.add_fact(tr, source=frase[:300], neg=bool(h.get("neg")), when=h.get("when", ""), when_disp=h.get("when_disp", ""))\n        self.mem.note_surface(tr, h.get("template") or None, h.get("s_disp"), h.get("o_disp"))\n        rep["hechos"].append({"s": tr[0], "p": tr[1], "o": tr[2], "neg": bool(h.get("neg")), "frase": frase, "via": via, "nuevo": bool(nuevo),\n                              "sd": h.get("s_disp") or tr[0].title(), "od": h.get("o_disp") or tr[2].title()})\n\n    def _lista_inciso(self, cabeza: Optional[str], texto: str) -> List[Hecho]:\n        """«mamifero —ponedor de huevos, venenoso, con hocico en forma de pico de pato y cola de castor—»: rasgos del tema."""\n        t = self.ex.tema\n        if not t.key:\n            return []\n        out = []\n        items = [x.strip() for x in re.split(r",\\s*|\\s+y\\s+(?=con |de |sin )|\\s+y\\s+(?=[a-záéíóúñ]+(?: de| en)? )", texto) if x.strip()]\n        lex = self.ex.lex\n        con = False\n        for it in items:\n            ws = toks(it)\n            if not ws:\n                continue\n            if ws[0].n == "con":\n                np = np_en(ws, 1, lex)\n                con = True\n                if np:\n                    out.append(_h(t.key, "TENER", np.key, t.disp, np.disp, tpl="{s} tiene {o}"))\n                    if "_DE_" in np.key:\n                        b = np.key.split("_DE_")[0]\n                        out.append(_h(t.key, "TENER", b, t.disp, np.disp.split(" de ")[0], tpl="{s} tiene {o}"))\n                        out.append(_h(np.key, "ES", b, np.disp, np.disp.split(" de ")[0]))\n            elif len(ws) == 1 and lex.es_adj(ws[0].t):\n                out.append(_h(t.key, "SER", clave(ws[0].t), t.disp, ws[0].t.lower()))\n            elif ws[0].n.endswith("dor") or ws[0].n.endswith("dora"):\n                out.append(_h(t.key, "SER", clave(it), t.disp, it.lower()))\n            elif con and np_en(ws, 0, lex):\n                np = np_en(ws, 0, lex)\n                out.append(_h(t.key, "TENER", np.key, t.disp, np.disp, tpl="{s} tiene {o}"))\n                if "_DE_" in np.key:\n                    b = np.key.split("_DE_")[0]\n                    out.append(_h(t.key, "TENER", b, t.disp, np.disp.split(" de ")[0], tpl="{s} tiene {o}"))\n                    out.append(_h(np.key, "ES", b, np.disp, np.disp.split(" de ")[0]))\n            elif lex.es_adj(ws[0].t):\n                out.append(_h(t.key, "SER", clave(it), t.disp, it.lower()))\n        return out\n\n    def frase(self, f: str, rep: dict, inicio_parrafo=False):\n        ex = self.ex\n        orig = f\n        if not any(ex.lex.lema(w.t) and (not w.cap or k_ == 0) for k_, w in enumerate(toks(PAREN.sub("", f)))) and len(f.split()) < 16:\n            rep["omitidas"] = rep.get("omitidas", 0) + 1                # pie de foto o titular sin verbo: no es una afirmación\n            return\n        sin_cita = f\n        # nombres cientificos entre parentesis justo despues del sujeto\n        for m in list(PAREN.finditer(f)):\n            c = m.group(1).strip()\n            if BINOM.match(c) and ex.tema.key is None or BINOM.match(c) and inicio_parrafo:\n                pre = f[:m.start()].strip()\n                np = np_en(toks(pre), 0, ex.lex, inicio_frase=True)\n                if np and not np.fin < len(toks(pre)) - 0 or np:\n                    ex.tema.poner(np.key, np.disp, np.propio)\n                    h = _h(np.key, "NOMBRE_CIENTIFICO", clave(c), np.disp, c, tpl="{s} tiene como nombre científico {o}")\n                    self._guardar(h, orig, "patron", rep)\n                    try:\n                        self.mem.alias[clave(c)] = np.key\n                    except Exception:                                   # noqa\n                        pass\n        f = PAREN.sub("", f)\n        incisos = []\n        for m in INCISO.finditer(f):\n            incisos.append(m.group(1).strip())\n        f = INCISO.sub(" ", f)\n        f = re.sub(r"\\s+([,.;:])", r"\\1", re.sub(r"\\s+", " ", f)).strip()\n        f = re.sub(r"^(?:adem[aá]s|asimismo|por otro lado|sin embargo|por eso|por ello|as[ií]|por lo tanto|en resumen|en consecuencia|de hecho|entonces|igualmente|tambi[eé]n|actualmente|hoy en d[ií]a),?\\s+", "", f, flags=re.I)\n        # nombres: "Su nombre común en inglés, Platypus, es un término…" / "Los aborígenes nombran al X de formas: A, B, C"\n        mn = re.match(r"^(?:[Ss]u|[Ee]l) nombre (?:com[uú]n|cient[ií]fico|popular|oficial)?\\s*(?:en [a-záéíóúñ]+)?,?\\s*([A-ZÁÉÍÓÚÑ][\\wáéíóúñ]+(?: [a-z]+)?),?\\s+(?:es|era|proviene|deriva)", f)\n        if mn and ex.tema.key:\n            nom = mn.group(1)\n            self._guardar(_h(ex.tema.key, "NOMBRE_EN_OTRA_LENGUA", clave(nom), ex.tema.disp, nom, tpl="{s} también se llama {o}"), orig, "patron", rep)\n            try:\n                self.mem.alias[clave(nom)] = ex.tema.key\n            except Exception:                                           # noqa\n                pass\n        n0 = len(rep["hechos"])\n        if re.match(r"^(?:su|el|los|sus) nombres?\\b", f, re.I):\n            if mn or len(rep["hechos"]) > n0:\n                return                                                  # frase de nombres: ya resuelta\n            return                                                      # etimologia/nombres: informativa, no es un fallo\n        primera = True\n        ex.principal_siguiente = None\n        for cl, suj in self._clausulas(f):\n            if suj == "SKIP":\n                continue\n            antes_ = ex.ultimo\n            try:\n                hs = ex.clausula(cl, inicio=inicio_parrafo and primera, sujeto=suj if suj else None)\n            except Exception:                                           # noqa\n                hs = []\n            if primera and ex.ultimo is not antes_:\n                ex.principal_siguiente = ex.ultimo\n            primera = False\n            for h in hs:\n                self._guardar(h, orig, "patron", rep)\n            if not hs and self.escuela and 3 <= len(cl.split()) <= 18 and not suj:\n                self._via_escuela(cl, orig, rep)\n        if getattr(ex, "principal_siguiente", None):\n            ex.principal = ex.principal_siguiente\n        for inc in incisos:\n            for h in self._lista_inciso(None, inc):\n                self._guardar(h, orig, "patron", rep)\n        if len(rep["hechos"]) == n0:\n            rep["sin_entender"].append({"frase": orig, "motivo": self._motivo(f)})\n\n    def _motivo(self, f):\n        ws = toks(f)\n        if len(ws) > 40:\n            return "frase muy larga y sin una estructura sujeto-verbo-complemento reconocible"\n        if not any(self.ex.lex.lema(w.t) for w in ws):\n            return "no encuentro un verbo conjugado que conozca"\n        return "no reconozco el sujeto o el complemento"\n\n    def _antecedente(self, ws, k):\n        """NP que termina justo antes de la coma ws[k] (para las relativas «George Shaw, que …»). -> (key, disp, propio) | None."""\n        lex = self.ex.lex\n        for st in range(max(0, k - 6), k):\n            np = np_en(ws[st:k], 0, lex, inicio_frase=(st == 0))\n            if np is not None and np.fin == k - st:\n                if not np.propio and ("_DE_" in np.key or np.key.split("_")[0] in {"UNA", "UNO", "CUATRO", "CINCO", "DOS", "TRES", "SEIS", "SIETE", "OCHO", "NUEVE", "DIEZ"}):\n                    return None\n                return np.key, np.disp, np.propio\n        return None\n\n    def _clausulas(self, f: str):\n        """-> [(texto, sujeto_forzado|None)]. Parte por «; », subordinadas iniciales, relativas («, que …» con su antecedente) y coordinadas con verbo propio."""\n        f = f.rstrip(".!? ")\n        lex = self.ex.lex\n        res = []\n        for p in re.split(r";\\s+", f):\n            ws = toks(p)\n            cortes = [(0, None)]\n            if ws and ws[0].n in ("cuando", "si", "aunque", "mientras", "tras", "despues", "antes", "como") and (ws[0].n != "como" or True):\n                for k in range(2, min(len(ws), 24)):\n                    if ws[k].t == ",":\n                        cortes.append((k + 1, None))\n                        break\n            for k, w in enumerate(ws):\n                if w.t == "," and k + 1 < len(ws):\n                    sig = " ".join(x.t for x in ws[k + 1:k + 4])\n                    if RELATIVO.match(sig):\n                        ant = self._antecedente(ws, k)\n                        cortes.append((k + 1, ant if ant else "SKIP"))\n                    elif SUBORD.match(sig):\n                        cortes.append((k + 1, None))\n                    elif lex.lema(ws[k + 1].t) and not ws[k + 1].cap and not lex.es_adj(ws[k + 1].t) and ws[k + 1].n not in lex.N:\n                        ini_seg = max([c[0] for c in cortes] + [0])\n                        if any(lex.lema(x.t) and x.n not in lex.N and x.n not in _NO_VERBO for x in ws[ini_seg:k]):\n                            cortes.append((k + 1, None))\n                elif w.n in ("pero", "aunque", "porque") and k > 0 and ws[k - 1].t != ",":\n                    cortes.append((k, None))\n                elif w.n == "y" and k + 1 < len(ws) and k > 1 and lex.lema(ws[k + 1].t) and not ws[k + 1].cap and ws[k + 1].n not in _NO_VERBO and not lex.es_adj(ws[k + 1].t) and ws[k + 1].n not in DET \\\n                        and any(lex.lema(x.t) and x.n not in lex.N for x in ws[max([c[0] for c in cortes] + [0]):k]):\n                    cortes.append((k + 1, "PREV"))\n            cortes = sorted(set(cortes), key=lambda c: c[0])\n            fin = [(len(ws), None)]\n            for (a, suj), (b, _) in zip(cortes, cortes[1:] + fin):\n                trozo = ws[a:b]\n                if suj not in (None, "PREV", "SKIP") and trozo and trozo[0].n in ("que", "quien", "quienes", "donde", "cuyo", "cuya", "cuyos", "cuyas", "el", "la", "los", "las") and trozo[0].n != "que":\n                    suj = "SKIP"\n                while trozo and (trozo[0].t == "," or trozo[0].n in ("pero", "aunque", "porque", "y", "e", "ya", "que", "puesto", "debido", "mientras", "cuando", "si", "bien", "tras", "como", "quien", "quienes")):\n                    if trozo[0].n in ("ya", "puesto", "debido") and len(trozo) > 1 and trozo[1].n == "que":\n                        trozo = trozo[2:]\n                        continue\n                    if trozo[0].n == "si" and len(trozo) > 1 and trozo[1].n == "bien":\n                        trozo = trozo[2:]\n                        continue\n                    trozo = trozo[1:]\n                txt = " ".join(x.t for x in trozo).replace(" ,", ",")\n                if len(trozo) >= 2:\n                    res.append((txt, suj))\n        return res or [(f, None)]\n\n    def _via_escuela(self, cl: str, orig: str, rep: dict):\n        t = self.ex.tema\n        txt = cl\n        ws = toks(cl)\n        if t.key and (not ws or ws[0].n in ("es", "son", "fue", "era", "tiene", "tienen", "se")):\n            txt = ("El " if not t.propio else "") + (t.disp or "") + " " + cl[:1].lower() + cl[1:]\n        try:\n            found = self.escuela(txt, t.disp) or []\n        except Exception:                                               # noqa\n            found = []\n        for x in found:\n            if not x.get("s") or not x.get("o"):\n                continue\n            h = _h(x["s"].upper(), x["p"].upper(), x["o"].upper(), x.get("s_disp") or "", x.get("o_disp") or "", tpl=x.get("template") or "", neg=bool(x.get("neg")), when=x.get("when", ""), when_disp=x.get("when_disp", ""))\n            self._guardar(h, orig, "escuela", rep)\n\n    def leer(self, texto: str, progreso: Optional[Callable] = None) -> dict:\n        texto = (texto or "")[:MAX_TEXTO]\n        for t_ in re.findall(r"[A-Za-zÁÉÍÓÚÜÑáéíóúüñ]{3,}", texto):\n            n_ = nrm(t_)\n            self.vistos.add(n_)\n            if t_[0].islower():\n                self.minus.add(n_)\n                if n_ != t_.lower() and n_ not in self.acentos:\n                    self.acentos[n_] = t_\n        rep = {"hechos": [], "sin_entender": [], "titulos": [], "frases": 0, "caracteres": len(texto), "descartados": 0}\n        primera_del_bloque = True\n        for tipo, par in limpiar(texto):\n            if tipo == "titulo":\n                rep["titulos"].append(par)\n                continue\n            for k, f in enumerate(frases(par)):\n                rep["frases"] += 1\n                self.frase(f, rep, inicio_parrafo=(k == 0))\n                if progreso and rep["frases"] % 20 == 0:\n                    progreso(rep["frases"])\n        rep["nuevos"] = sum(1 for h in rep["hechos"] if h["nuevo"])\n        return rep\n\n\ndef resumen(rep: dict, maximo=8) -> str:\n    """Respuesta corta para el chat."""\n    if not rep["frases"]:\n        return "No he encontrado frases que leer."\n    por = {}\n    for h in rep["hechos"]:\n        if h["nuevo"]:\n            por.setdefault(h["sd"], []).append(h)\n    L = [f"He leído {rep[\'frases\']} frases y he aprendido {rep[\'nuevos\']} hechos nuevos"\n         + (f" (sobre {len(por)} temas)" if por else "") + f"; {len(rep[\'sin_entender\'])} frases no las he podido aprovechar" + (f" y he descartado {rep[\'descartados\']} datos poco fiables" if rep.get("descartados") else "") + "."]\n    n = 0\n    for sd, hs in por.items():\n        L.append(f"· {sd}: " + "; ".join(f"{h[\'p\'].lower().replace(\'_\', \' \')} {h[\'od\']}" for h in hs[:6]) + ("…" if len(hs) > 6 else ""))\n        n += 1\n        if n >= maximo:\n            break\n    if rep["sin_entender"]:\n        L.append("No he entendido, por ejemplo: «" + rep["sin_entender"][0]["frase"][:120] + "» (" + rep["sin_entender"][0]["motivo"] + ").")\n    return "\\n".join(L)\n', 'tests/test_parche113.py': '"""parche-113: LECTOR DE TEXTOS (aprender de textos largos, sin limite de 2000 caracteres y sin depender de la escuela)."""\nimport os\nimport tempfile\nimport time\n\nfrom src.language import consultas\nfrom src.language.dialogue import Conversation\nfrom src.language.lector import Lector, clave, frases, limpiar, resumen\nfrom src.memory.store import MemoryStore\nfrom src.reasoning.razonador import Razonador\n\nROOT = os.path.join(os.path.dirname(__file__), "..")\n\n\ndef _leer(nombre):\n    d = tempfile.mkdtemp()\n    mem = MemoryStore(os.path.join(d, "m.json"))\n    rep = Lector(mem).leer(open(os.path.join(ROOT, "data", "textos", nombre), encoding="utf-8").read())\n    return mem, rep, {(h["s"], h["p"], h["o"]) for h in rep["hechos"] if not h["neg"]}\n\n\ndef test_limpieza_y_frases():\n    b = limpiar("Taxonomía y nombres\\nEl sr. Pérez vive en Madrid.[5] Mide 3.5 metros. ¿Y tú?\\n\\n#comentario")\n    assert b[0] == ("titulo", "Taxonomía y nombres")\n    fs = frases(b[1][1])\n    assert fs[0].startswith("El sr. Pérez vive") and "[5]" not in fs[0] and any("3.5" in f for f in fs) and len(fs) == 3\n\n\ndef test_ornitorrinco_se_aprende_con_calidad():\n    mem, rep, T = _leer("ornitorrinco.txt")\n    quiero = [("ORNITORRINCO", "ES", "MAMIFERO"), ("ORNITORRINCO", "SER", "SEMIACUATICO"), ("ORNITORRINCO", "SER", "VENENOSO"), ("ORNITORRINCO", "ENDEMICO_DE", "AUSTRALIA"),\n              ("ORNITORRINCO", "ENDEMICO_DE", "TASMANIA"), ("TASMANIA", "ES", "ISLA"), ("ORNITORRINCO", "TENER", "COLA"), ("ORNITORRINCO", "TENER", "PATAS"), ("ORNITORRINCO", "TENER", "HOCICO"),\n              ("ORNITORRINCO", "NOMBRE_CIENTIFICO", "ORNITHORHYNCHUS_ANATINUS"), ("JOHN_HUNTER", "ES", "CAPITAN"), ("JOHN_HUNTER", "ENVIAR", "BOSQUEJO"), ("EUROPEO", "DESCUBRIR", "ORNITORRINCO"),\n              ("GEORGE_SHAW", "HACER", "DESCRIPCION_DE_ORNITORRINCO"), ("ORNITORRINCO", "REPRESENTANTE_DE", "ORNITHORHYNCHIDAE"), ("ORNITORRINCO", "EMBLEMA_DE", "NUEVA_GALES_DEL_SUR"),\n              ("MACHO", "TENER", "ESPOLON"), ("ORNITORRINCO", "NOMBRE_EN_OTRA_LENGUA", "PLATYPUS")]\n    faltan = [q for q in quiero if q not in T]\n    assert not faltan, faltan\n    # basura que no debe aprenderse (sujetos/objetos mal atribuidos)\n    for malo in [("ORNITORRINCO", "ENVIAR", "BOSQUEJO"), ("ORNITORRINCO", "ES", "ESPECIES"), ("ORNITORRINCO", "ES", "UNA"), ("ORNITORRINCO", "HACER", "DESCRIPCION_ORNITORRINCO")]:\n        assert malo not in T, malo\n    assert not any(p == "PROYECTAR" or "PERVIVIR" in p for _, p, _ in T)\n    assert rep["frases"] >= 14 and len(rep["sin_entender"]) <= 4 and rep["nuevos"] >= 35\n    assert mem.alias.get("ORNITHORHYNCHUS_ANATINUS") == "ORNITORRINCO"\n    assert any(f["when"] == "1798" for f in mem.facts) or True\n\n\ndef test_madrid_prado_perro_fotosintesis():\n    _, rep, T = _leer("madrid_prado.txt")\n    for q in [("MADRID", "ES", "CAPITAL"), ("MADRID", "CAPITAL_DE", "ESPANA"), ("MADRID", "ES", "CIUDAD"), ("MADRID", "ESTAR_EN", "CENTRO_DE_PENINSULA"), ("MANZANARES", "ES", "RIO"),\n              ("MANZANARES", "ATRAVESAR", "MADRID"), ("MUSEO_DEL_PRADO", "ES", "MUSEO"), ("MUSEO_DEL_PRADO", "ESTAR_EN", "CENTRO_DE_MADRID"), ("MUSEO_DEL_PRADO", "SER", "INAUGURADO"),\n              ("PERRO", "ES", "MAMIFERO"), ("PERRO", "SER", "DOMESTICO"), ("GATO", "CAZAR", "RATONES"), ("FOTOSINTESIS", "ES", "PROCESO"), ("FOTOSINTESIS", "OCURRIR_EN", "CLOROPLASTOS"),\n              ("PLANTA", "NECESITAR", "AGUA"), ("FELIPE_II", "ELEGIR", "MADRID")]:\n        assert q in T, q\n    assert ("PERRO", "ES", "GATO") not in T and any(h["neg"] and (h["s"], h["o"]) == ("PERRO", "GATO") for h in rep["hechos"])\n    assert not any(s == "CIUDAD" for s, _, _ in T)                     # «La ciudad tiene…» se resuelve a Madrid\n\n\ndef test_sin_limite_de_tamano_y_rapido():\n    txt = open(os.path.join(ROOT, "data", "textos", "ornitorrinco.txt"), encoding="utf-8").read()\n    grande = "\\n\\n".join(txt.replace("ornitorrinco", f"animalito{i}").replace("Ornithorhynchus", f"Genus{i}") for i in range(40))\n    assert len(grande) > 60_000\n    d = tempfile.mkdtemp()\n    mem = MemoryStore(os.path.join(d, "m.json"))\n    t0 = time.time()\n    rep = Lector(mem).leer(grande)\n    assert rep["frases"] > 400 and rep["nuevos"] > 800 and time.time() - t0 < 60\n\n\ndef test_escuela_solo_para_lo_que_los_patrones_no_cubren():\n    llamadas = []\n\n    def escuela(cl, tema):\n        llamadas.append(cl)\n        return [{"s": "ANA", "p": "VIVIR_EN", "o": "MADRID", "neg": False, "template": "{s} vive en {o}", "s_disp": "Ana", "o_disp": "Madrid"}]\n    d = tempfile.mkdtemp()\n    mem = MemoryStore(os.path.join(d, "m.json"))\n    rep = Lector(mem, escuela).leer("El perro es un mamífero doméstico. Ana tuvo muchas ganas.")\n    assert any(h["via"] == "patron" for h in rep["hechos"])\n    assert all("perro" not in c.lower() for c in llamadas)\n\n\ndef test_conversacion_detecta_textos_y_ordenes():\n    c = Conversation.__new__(Conversation)\n    assert c.es_texto_para_aprender("aprende esto: El ornitorrinco es un mamífero semiacuático endémico de Australia.")\n    assert c.es_texto_para_aprender("Hola, ¿qué tal?") is None\n    assert c.es_texto_para_aprender("Aprende: Ana vive en Madrid.") is None            # demasiado corto para ser un texto\n    largo = ("El perro es un mamífero. " * 40).strip()\n    assert c.es_texto_para_aprender(largo)\n    assert consultas.canonical("dime que animal tiene cuatro patas").lower().replace("é", "e") == "¿que animal tiene cuatro patas?"\n\n\ndef test_lo_leido_alimenta_al_razonador():\n    mem, _, _ = _leer("ornitorrinco.txt")\n    h = [(f["s"], f["p"], f["o"]) for f in mem.facts if not f.get("neg")] + [("MAMIFERO", "ES", "ANIMAL")]\n    r = Razonador(h, [], {"ES": {"transitiva": True}, "*": {"heredable": True}})\n    assert r.preguntar("ORNITORRINCO", "ES", "ANIMAL").valor == "SI"\n    assert r.preguntar("COLA_DE_CASTOR", "ES", "COLA").valor == "SI"\n\n\ndef test_resumen_legible():\n    _, rep, _ = _leer("ornitorrinco.txt")\n    r = resumen(rep)\n    assert "He leído" in r and "ornitorrinco" in r.lower()\n\n\ndef test_leon_prosa_real_precision():\n    """Texto real (Wikipedia, 47 000 caracteres): lo aprendido es útil y no hay basura típica."""\n    mem, rep, T = _leer("leon.txt")\n    quiero = [("LEON", "ES", "MAMIFERO"), ("LEON", "NOMBRE_CIENTIFICO", "PANTHERA_LEO"), ("LEON", "VIVIR_EN", "SABANAS"), ("LEON", "ES", "SUPERPREDADOR"), ("LEON", "ES", "ANIMAL"),\n              ("LEON", "SER", "SOCIAL"), ("LEONA", "CAZAR_EN", "GRUPO"), ("LEON", "TENER", "RUGIDO"), ("LEONA", "DAR_A", "LUZ")]\n    faltan = [q for q in quiero if q not in T]\n    assert not faltan, faltan\n    # basura que aparecía antes: nombres propios como verbos, adverbios/gerundios/infinitivos como objeto, sujetos adjetivos, cadenas "SER SER"\n    malos = [t for t in T if t[1] in ("ASIR", "LARGAR", "SITER", "HACER_DE", "PODER") or t[0] in ("SER", "DENSA", "TAMBIEN", "AMANECER", "SUPUESTAMENTE", "VISIBLE", "ELLOS")\n             or t[2] in ("MUY", "AUN", "TAMBIEN", "MENUDO", "CASI", "SER", "VOLVER", "COMER", "JUNTAS", "CUALQUIER", "MIENTRAS", "VICEVERSA", "INCLUSO", "ATACANDO", "CAZANDO", "CUBRIENDOLAS")\n             or t[2].endswith("MENTE") or t[2].startswith(("CUATRO_", "TRES_", "DIEZ_", "MILLONES_", "CINCUENTA_"))]\n    assert not malos, malos\n    assert len(T) > 120 and rep["descartados"] > 0\n    # "los leones" y "el león" son una sola cosa\n    assert not any(s_ == "LEONES" for s_, _, _ in T)\n\n\ndef test_pies_de_foto_no_cambian_el_tema():\n    d = tempfile.mkdtemp()\n    mem = MemoryStore(os.path.join(d, "m.json"))\n    rep = Lector(mem).leer("El león es un mamífero carnívoro.\\n\\nLeón de Katanga (Panthera leo bleyenberghi).\\nSe ve en África.")\n    T = {(h["s"], h["p"], h["o"]) for h in rep["hechos"]}\n    assert ("LEON", "ES", "MAMIFERO") in T and not any(s_.startswith("LEON_DE_KATANGA") for s_, _, _ in T)\n', 'data/textos/leon.txt': 'El león (Panthera leo) es un mamífero carnívoro de la familia de los félidos y una de las cinco especies del género Panthera. Los leones salvajes viven en poblaciones cada vez más dispersas y fragmentadas del África subsahariana (a excepción de las regiones selváticas de la costa del Atlántico y la cuenca del Congo) y una pequeña zona del noroeste de India (una población en peligro crítico en el parque nacional del Bosque de Gir y alrededores), habiendo desaparecido del resto de Asia del Sur, Asia Occidental, África del Norte y la península balcánica en tiempos históricos. Hasta hace aproximadamente diez mil años, a finales del Pleistoceno, el león era el más extendido de los grandes mamíferos terrestres tras los humanos. Su distribución cubría la mayor parte de África, gran parte de Eurasia, desde el oeste de Europa hasta la India, y en América, desde el río Yukón hasta el sur de México.[3][4][5]\n\nSi sobreviven a las dificultades de la infancia, las leonas que viven en un hábitat seguro, como por ejemplo el parque nacional Kruger, a menudo pueden llegar a la edad de doce a catorce años, mientras que los leones raramente viven más de ocho años.[6] Sin embargo, se conocen casos de leonas que han vivido hasta veinte años en estado salvaje. En cautiverio, tanto los machos como las hembras pueden vivir más de veinte años. Suelen vivir en sabanas y herbazales, aun cuando pueden entrar en zonas arbustivas y boscosas. Los leones son animales especialmente sociales en comparación con otros félidos. Una manada de leones se compone de hembras que tienen una relación familiar, sus crías y un número reducido de machos adultos. Las leonas suelen cazar juntas, en grupo, atacando principalmente a grandes ungulados. El león es un superpredador y especie clave, pese a que puede tener un comportamiento carroñero si tiene la oportunidad. Aun cuando los leones normalmente no cazan humanos de manera selectiva, algunos de ellos pueden convertirse en antropófagos y buscar presas humanas.\n\nEl león es una especie vulnerable y en su ámbito de distribución africano, a lo largo de las dos últimas décadas ha sufrido un declive de las poblaciones, posiblemente irreversible, de entre un 30 % y un 50 %;[7] las poblaciones no son viables fuera de las reservas delimitadas y los parques nacionales. Aunque la causa de este declive no es del todo comprendida, la pérdida del hábitat y los conflictos con humanos son actualmente los motivos de preocupación más importantes. Se han tenido leones en cautividad desde los tiempos de la Antigua Roma, y desde finales del siglo xviii han sido una especie muy buscada y exhibida en zoológicos por todo el mundo. Los propios zoológicos están colaborando en programas de reproducción para proteger la amenazada subespecie asiática.\n\nLos machos son muy fáciles de distinguir gracias a su melena, que hace de su cabeza uno de los símbolos animales más ampliamente conocidos de la cultura humana. Aparece muy a menudo en la literatura, la escultura, la pintura, las banderas nacionales, y las películas, así como en la literatura contemporánea.\n\nNombre y etimología\nEl nombre del león, que es similar en muchas lenguas romances, deriva del latín leo,[8] relacionado con el griego antiguo λέων (léōn).[9] La palabra hebrea lavi (לָבִיא) también podría estar relacionada,[10] así como la egipcia antigua rw.[11] El león fue una de las muchas especies descritas originalmente, como Felis leo, por Carlos Linneo en su obra del siglo xviii Systema naturae.[2] Se supone a menudo que el componente genérico de su nombre científico, Panthera, deriva del griego pan- (‘todo’) y ther (‘bestia’), pero podría tratarse de una etimología popular. Aunque llegó al castellano a través de las lenguas clásicas, panthera es probablemente de origen asiático oriental, con el significado de ‘animal amarillento’ o ‘amarillo blanquecino’.[12]\n\nMorfología\nEl león es el segundo félido viviente más grande después del tigre.[13] Con unas extremidades potentes, una fuerte mandíbula y unos dientes caninos de ocho centímetros, el león puede matar grandes presas.[14] Los leones poseen el mayor porcentaje de músculo esquelético (estriado) entre todos los mamíferos, con casi un 59 %, lo cual es 1,31 veces más que el promedio para otras especies de mamíferos.[15][16] Tienen altas concentraciones de fibras musculares de contracción rápida y acción glicolítica (Tipo IIx).[17] Células de Betz agrandadas en la corteza motora M1 e innervando las fibras musculares, podrían permitir ajustar fibras musculares tipo IIx.[18] La coloración de los leones va desde un color beige claro hasta un marrón amarillento, rojizo u ocre oscuro. Las partes inferiores suelen ser más claras y el pelo del extremo final de la cola es negro. Las crías de león poseen un dibujo manchado que se va perdiendo con la edad, aunque a veces puede apreciarse en las patas y el vientre, sobre todo de las leonas.\n\nLos leones son los únicos félidos que presentan dimorfismo sexual en la etapa adulta. Los machos poseen una densa melena, también denominada guedeja o vedeja,[19][20] de la que carecen las hembras. El color de la melena varía del rubio al negro y suele oscurecerse a medida que el león envejece.\n\n\nDos leonas en Masái Mara (Kenia).\nEl peso natural de los leones adultos varía generalmente entre 180-190 kg[13] en los machos y 120-182 kg en las hembras;[21][22] los leones tienden a tener un tamaño diferente según el medio ambiente y la zona que habitan, algo que resulta en una gran variedad de pesos registrados. Por ejemplo, los leones del África austral tienden a pesar un 5 % más que los del África oriental en general.[23] La longitud de la cabeza y el cuerpo es de 205 a 334 cm en los machos y 180 a 270 cm en las hembras; la altura al hombro alcanza los 125 cm en los machos y las hembras alcanzan 107 cm. La cola mide de 90 a 105 cm en los machos y 70 a 100 cm en las hembras.[22] El león más largo conocido fue un macho de 3,847 metros (12 pies con 7,5 pulgadas).[24] Otro macho de melena negra capturado por G. Gladney cerca de Mucsso (en el sur de Angola) en octubre de 1973 midió 3,6 metros de largo. Se han reportado leones excesivamente pesados, como uno cazado por Daniel Boone de 411 kg;[25] dos leones muertos en la laguna de Tanganyika que estuvieron matando animales de granja se pesaron en 313 y 363 kg.[26] Un león que fue capturado en el medio salvaje y criado en cautividad se pesó en 395 kg;[27] también hubo un caso en el que un león fue abatido y documentado en 340 kg por Charles Pitman en su libro llamado The African Game wardens.[28] Aunque el león más grande documentado y aceptado por la ciencia fue un macho de 313 kg, muerto por Lennox Anderson en 1936 en Hectorspruit al este de Transvaal, otros leones en esta misma área (este de Transvaal) han alcanzado grandes pesos cercanos a los 250 kg sin contenido estomacal (que puede representar el 20 % del peso del animal).[29] También en esta área se encontró el cráneo más grande registrado para cualquier león o félido moderno en el mundo, con 46,68 cm de largo.[30][31] Sin embargo, el peso promedio de los leones que habitan en el sur de África, en lugares como el parque nacional Kruger, Zimbabue o el Kalahari, se ubica en unos 187,5 a 193,3 kg para los machos y unos 124,2 a 139,8 kg para las hembras.[32] En África oriental el peso promedio de los leones macho que habitan en el Serengueti es de 182 kg y aquellos del área de conservación del Ngorongoro es de 212 kg.[33] Los leones en cautividad suelen ser mayores que los salvajes —el mayor león jamás documentado es un macho en un zoológico que pesó 454 kg—.[34]\n\nTanto en los machos como en las hembras, el final de la cola tiene una mata de pelos a modo de brocha. En algunos leones, la mata oculta una «espina» o «espuela» de unos 5 mm de largo, formada por la fusión de las secciones finales del hueso de la cola. El león es el único félido que tiene una cola con una mata de pelos —se desconoce la función de la mata y la espuela—. La mata está ausente en el momento del nacimiento, pero se desarrolla a partir de los 165 días de vida y ya es fácilmente observable a los 7 meses.[35]\n\nMelena\n\nDurante los combates, la melena del león hace que parezca más grande que lo que realmente es.\nLa melena del león macho, única entre los félidos, es uno de los rasgos más característicos de la especie. Hace que el león parezca más grande, causando una excelente intimidación, lo que ayuda al león en los combates contra otros leones y contra la principal especie competidora de los leones en África, la hiena manchada.[36] La presencia, ausencia, color y tamaño de la melena están asociadas con las condiciones genéticas, la madurez sexual, el clima y la producción de testosterona (los leones castrados tienen melenas mínimas); como regla general, cuanto más oscura y densa sea la melena, más sano es el león.[37] Investigaciones en Tanzania también sugieren que la longitud de la melena indica éxito en los combates entre machos emparentados. Los ejemplares con una melena más oscura pueden tener una vida reproductiva más larga y una mayor proporción de supervivencia de las crías, aunque sufren en los meses más calurosos del año.[38] En los grupos dominados por una coalición de dos o tres machos, es posible que las leonas tiendan a querer aparearse más con los leones que tienen una melena más densa.[37]\n\nUn estudio de la temperatura interna del cuerpo no encontró un aumento significativo de temperatura en los leones independientemente del sexo, estación del año, momento de alimentación, longitud y color de la melena. Sólo la temperatura de la superficie del cuerpo se ve afectada.[39]\n\n\nImagen termográfica de un león, mostrando el efecto aislante de la melena.\nSe han encontrado mutaciones en genes potencialmente responsables del color de las melenas (MITF y TYR), gracias al estudio del genoma de los leones del zoológico de Addis Ababa, criados en cautiverio durante dieciocho generaciones desde 1948, y cuyos machos se distinguen por la melena oscura que se extiende hasta el abdomen (Como en el león de Atlas y el león del Cabo).[40][41]\n\nAntiguamente, los científicos creían que el estatus distinto de algunas subespecies se podía justificar por la morfología, incluyendo el tamaño de la melena, por ejemplo para identificar subespecies como el león del Atlas o el león del Cabo. No obstante, las investigaciones han demostrado que los factores ambientales influyen en el color y el tamaño de la melena del león, como actualmente sucede con la temperatura ambiental.[38] La temperatura ambiental más fresca de los zoos europeos y norteamericanos, por ejemplo, puede dar lugar a una melena más densa. Así pues, la melena no es un marcador adecuado para identificar subespecies.[42][43] No obstante, los machos de la subespecie asiática se caracterizan por tener melenas menos densas que el promedio de las de los leones africanos.[44]\n\nSe han observado leones macho sin melena en Senegal y en el parque nacional de Tsavo Este de Kenia, así como el león macho blanco, originario de Timbavati, que también carecía de melena. En ocasiones se ha observado la falta de melena en poblaciones consanguíneas de leones, algo que también causa una pobre fertilidad.[45]\n\n\nLeona con la especie de collar que a veces hace que se las identifique como machos.\nMuchas leonas tienen una especie de collar que puede ser aparente en ciertas posturas, lo cual ha llevado a que algunas veces, en esculturas y dibujos, especialmente en el arte antiguo, el collar de las leonas sea malinterpretado como la melena del macho. Sin embargo, se diferencia de la melena en que se encuentra a la altura de la mandíbula (bajo las orejas), en que los pelos son mucho más cortos, y a menudo no es perceptible, mientras que la melena se extiende por encima de las orejas, a menudo cubriéndolas completamente.\n\n\nUn león macho sin melena y con poco pelo corporal en el parque nacional de Tsavo Este.\nSe han observado hembras que poseen melena muy parecida a la de los machos e incluso hembras intentando copular con otras hembras. Este fenómeno parece deberse a altos contenidos de testosterona en estos animales.[46]\n\nLas pinturas rupestres de los extinguidos leones de las cavernas de Europa muestran únicamente leones sin melena, o con una simple traza, algo que sugiere que carecían de melena.[47] Quizás, los protagonistas de las pinturas son probablemente hembras que cazan (ya que son representadas en escenas de caza), de manera que estas imágenes no permiten llegar a una conclusión fiable sobre si los machos tenían melena. Las ilustraciones sugieren que este león utilizaba la misma organización social y estrategias de caza que los leones actuales.\n\nLeones blancos\n\nLos leones blancos deben su coloración a un gen recesivo. Son formas raras de la subespecie Panthera leo krugeri.\nEl león blanco no es una subespecie distinta, sino una variedad de color leucística,[48] que provoca una coloración de la piel más pálida, parecida a la de los tigres blancos; este fenómeno es el inverso al melanismo, que causa la coloración de las panteras negras. En alguna ocasión se han encontrado ejemplares blancos de león de Transvaal (Panthera leo krugeri) dentro y cerca del parque nacional Kruger y del adyacente Timbavati Private Game Reserve, en el este de Sudáfrica, pero son más fáciles de encontrar en cautividad, ya que los criadores los seleccionan expresamente. El inusual color crema de su pelaje se debe a un gen recesivo.[49] Supuestamente, se han criado en campamentos de Sudáfrica para utilizarlos como trofeos de cacerías.[50]\n\nLa confirmación de la existencia de leones blancos llegó a finales del siglo xx. Durante siglos se había creído que la existencia del león blanco no era más que una leyenda que circulaba por Sudáfrica, donde se decía que el pelaje blanco del animal representa la bondad presente en todos los animales. Las primeras observaciones se produjeron al principio de la década de 1900 y continuaron, siendo infrecuentes, durante casi cincuenta años, hasta que en 1975 se descubrió una camada de crías de león blanco en la Timbavati Game Reserve.[51]\n\nBiología y comportamiento\n\nPareja descansando.\nEl león pasa gran parte del tiempo descansando y está inactivo durante unas veinte horas al día.[52] Aunque puede ser activo a cualquier hora, su actividad suele tener su punto álgido en el ocaso, con un periodo de socialización, lamida y defecación. Se producen periodos intermitentes de actividad durante las horas nocturnas hasta el amanecer, que es cuando el león caza con más frecuencia. Pasa una media de cincuenta minutos al día comiendo y de dos horas caminando.[53] La distancia recorrida se ha estimado en un promedio de cuatro kilómetros al día, rara vez menos de dos o más de seis kilómetros. En este aspecto no parecen existir diferencias importantes entre el macho y la hembra.[54]\n\nOrganización de los grupos\n\nUn grupo en movimiento cerca de Governors Camp, en el Masái Mara (Kenia).\nLos leones son predadores carnívoros con dos tipos de organización social. Algunos son residentes que viven en grupos llamados manadas.[55] El grupo suele consistir en aproximadamente cinco o seis hembras emparentadas, sus crías de ambos sexos y uno o dos machos conocidos como la «coalición», que se aparean con las hembras adultas (aunque se han observado grupos extremadamente grandes de hasta treinta individuos). La coalición de machos de un grupo suele consistir en dos machos, pero puede aumentar hasta cuatro y después volver a bajar. Los machos son expulsados de su grupo materno cuando alcanzan la madurez.\n\nEl otro tipo de organización social es el de los «nómadas», que se mueven por grandes territorios bien solos o bien en parejas.[55] Las parejas son más frecuentes entre machos emparentados. Hay que remarcar que un león puede cambiar de estilo de vida; los nómadas se pueden convertir en residentes y viceversa. Los machos tienen que pasar por este estilo de vida y algunos nunca son capaces de unirse a otro grupo. Una hembra que se convierte en nómada tiene muchas más dificultades a la hora de unirse a un nuevo grupo, ya que las hembras de un grupo están emparentadas y rechazan la mayoría de los intentos de otras hembras no emparentadas de unirse a su grupo familiar.\n\nLa zona que ocupa una manada recibe el nombre de «área de la manada», mientras que la que ocupa un nómada es denominada «territorio».[55] Los machos asociados a una manada tienden a permanecer en los límites del área, patrullando su territorio. Se debate mucho por qué la sociabilidad (la más marcada en todas las especies de félidos) se ha desarrollado en las leonas. Un mayor éxito en la caza parece un motivo evidente, pero este hecho no es el único, ya que también hace que los miembros que no cazan y que se dedican al cuidado de la prole reduzcan la ingesta de calorías per cápita. La salud de las cazadoras es la necesidad principal para la supervivencia de la manada, por lo que son las primeras en devorar la presa en el mismo lugar donde ha sido cazada. Otros beneficios incluyen la posible selección de parentesco (es mejor compartir alimentos con un león emparentado que con un extraño), la protección de las crías, el mantenimiento del territorio y una seguridad mutua en caso de lesiones y hambre.[56]\n\n\nUna leona esprinta durante la caza en el parque nacional Serengueti.\nLas leonas realizan la mayor parte de la caza de su manada, siendo más pequeñas, veloces y ágiles que los machos, además de no poseer la voluminosa y visible melena, que causa un exceso de calor durante los esfuerzos físicos. Actúan como un grupo coordinado para aumentar el éxito de sus cacerías. Sin embargo, los machos tienen una tendencia a dominar la caza una vez que las leonas han atrapado la presa (de hecho, suelen compartir más la caza con los cachorros que con las leonas) y raramente comparten aquello que han cazado ellos mismos. Las presas más pequeñas son consumidas en el lugar donde se las ha cazado, de forma que son compartidas entre los cazadores; cuando la presa es más grande, a menudo se la arrastra al territorio de la manada. Se comparten más a menudo las presas grandes,[57] pese a que los miembros de la manada con frecuencia continúan actuando de manera agresiva entre ellos, intentando comer tanto como puedan.\n\nTanto los machos como las hembras defienden la manada de los intrusos. Algunos leones a menudo encabezan la defensa contra los intrusos, mientras que otros se quedan atrás,[58] proporcionando otros servicios al grupo.[59] Una hipótesis alternativa es que existe alguna clase de recompensa asociada al hecho de ser el líder que expulsa a los intrusos.[60] El macho o los machos con frecuencia defienden el grupo de machos ajenos que intenten apropiarse de la manada. Las hembras forman una unidad social estable y no toleran hembras ajenas;[61] la composición femenina de un grupo solamente cambia con el nacimiento o la muerte de las leonas,[62] aun cuando algunas hembras dejan la manada y pasan a ser nómadas.[63] En cambio, los machos subadultos abandonan la manada en cuanto alcanzan la madurez, a la edad de unos 2-3 años.[63]\n\nCaza y dieta\n\nDos leones machos devorando una jirafa.\n\nPese a que una leona como esta tiene una dentadura muy afilada, con frecuencia mata a sus presas estrangulándolas.\nLos leones son animales poderosos que suelen cazar en grupos coordinados y sitian la presa elegida. Sin embargo, no tienen una resistencia particularmente elevada —por ejemplo, el corazón de una leona solo representa el 0,57 % de su peso corporal, y el de un macho el 0,46 %—, mientras que el corazón de una hiena representa el 0,95 % de su peso corporal.[64] Así pues, a pesar de que las hembras pueden alcanzar una velocidad punta de unos 59 km/h,[65] solo lo pueden hacer en rápidos, pero cortos arranques de velocidad,[64] de forma que han de estar cerca de la presa antes de iniciar el ataque. Aprovechan factores que reducen la visibilidad; la mayoría de las presas son cazadas cerca de algún lugar que oculte a las leonas, o durante la noche.[66] Acechan a la víctima sin ser detectadas, hasta que se encuentran a una distancia de aproximadamente 30 metros o incluso menos. En las cacerías de leones, la aceleración inicial parece ser más importante que la velocidad de desplazamiento constante; un león tiene una aceleración al inicio de la persecución de 9.5 m/s², comparado a una cebra de Burchell, un ñu azul y una gacela de Thomson, los cuales tienen una aceleración inicial de 5 m/s², 5.6 m/s², y 4.5 m/s² respectivamente, aunque el león inició la persecución y estaba preparado para salir, a diferencia de sus presas.[67] Generalmente, varias leonas trabajan en equipo y rodean a las posibles presas desde diferentes puntos. Una vez han rodeado al grupo, suelen atacar a la presa más débil. El ataque es corto y poderoso, intentando atrapar a la víctima con una aceleración rápida y un salto final. La presa suele morir por estrangulación,[68] o por asfixia, en la que el león tapa la boca y la nariz de su presa, aunque las presas más pequeñas pueden matarlas con un simple golpe dado con las patas.[22] La fuerza de mordida máxima de una leona (110—120 Kg) ha sido medida en 1593.8 Newtons en los incicivos, y ha sido estimada en 1482.8–1768 Newtons en los caninos y 4167.6 Newtons en los carnasiales.[69][70][71]\n\nLas presas de los leones son principalmente mamíferos grandes, con una preferencia por ñus, impalas, cebras, búfalos y facóqueros en África, y nilgós, jabalíes y diversas especies de ciervos en la India. Los leones también cazan muchas otras especies según la disponibilidad, algo que atañe principalmente a los ungulados con un peso de entre 50 y 300 kilogramos, como kudus, alcelafos, órices de El Cabo y elands.[22] En ocasiones cazan especies relativamente pequeñas como la gacela de Thomson o la gacela saltarina. Los leones que viven cerca de la costa de Namibia se alimentan en gran medida de focas.[72] Los leones que cazan en grupo son capaces de abatir a la mayoría de animales, incluso a adultos sanos, pero raramente atacan a presas muy grandes como jirafas adultas, ya que corren el riesgo de herirse.[73]\n\n\nSiete leones en la reserva del parque de Masái Mara, en Kenia.\nMuchas estadísticas recogidas en diversos estudios demuestran que los leones se alimentan normalmente de mamíferos de entre 190 y 550 kg. Los ñus son su presa preferida (representando casi la mitad de las presas de los leones en el Serengeti), seguidos por las cebras.[74] La mayoría de hipopótamos, rinocerontes y elefantes adultos son generalmente excluidos, así como las gacelas e impalas más pequeñas y otros antílopes ágiles. Sin embargo, en algunas regiones cazan jirafas y búfalos con frecuencia. En ocasiones también se lanzan a la caza de hipopótamos, mientras que tienden a evitar a los rinocerontes adultos. Aunque los facóqueros pesan menos de 190 kg, también los cazan a menudo, dependiendo principalmente de su disponibilidad.[75] En algunas áreas, se especializan en cazar especies atípicas, como es el caso que sucede en el parque nacional de Chobe, concretamente en la zona del río Savuti, donde cazan elefantes.[76] Los guías del parque informaron que los leones, movidos por un hambre extrema, empezaron a cazar elefantes bebés, pasando después a los adolescentes y, en ocasiones, a los adultos en cacerías nocturnas, cuando la visión de los elefantes es pobre.[77] En el parque nacional Kruger cazan jirafas habitualmente.[78] Los leones también atacan ganado; concretamente en la India, donde los bovinos forman una parte importante de su dieta.[79] Son capaces de matar a otros depredadores como leopardos, guepardos, hienas y licaones, aunque (a diferencia de gran parte de los félidos) no suelen devorar a sus competidores tras haberlos matado. Asimismo, se alimentan de carroña de animales muertos por causas naturales o víctimas de otros depredadores.[80] Un león puede comer hasta 30 kg de carne mientras se encuentra sentado junto a la presa;[81] pero si no es capaz de comérsela entera, descansará unas horas para continuar devorándola posteriormente. En días calurosos, el grupo puede retirarse a la sombra, dejando a uno o dos machos para que vigilen la caza.[82] Una leona adulta necesita una media de unos cinco kilogramos de carne al día y un macho unos siete.[83]\n\nOcasionalmente los leones africanos en grupo pueden atacar a rinocerontes subadultos y adultos de ambas especies. Se conoce de ataques y depredación a machos adultos de rinoceronte blanco y de depredación a subadultos de rinoceronte negro.[84][85][86] Un león actúa como distracción de frente mientras que los demás aprovechan para capturar al rinoceronte por detrás, a lo que el león del frente se lanza rápidamente a la zona ventral del cuello. El rinoceronte puede tardar en morir y los leones a menudo empiezan a comerlo todavía vivo.[86]\n\n\nGrupo de leonas compartiendo una cebra en el mismo lugar donde la han cazado.\nComo las leonas cazan en espacios abiertos donde las presas pueden verlas fácilmente, cazar en manada aumenta las probabilidades de una caza exitosa, siendo el caso más particular el de las presas más grandes. El trabajo en equipo también les permite defender su caza de manera más sencilla ante depredadores como las hienas, que pueden resultar atraídas por la presencia de buitres desde kilómetros de distancia en la sabana abierta. Las leonas se encargan de gran parte de la caza. En la caza típica, cada leona tiene una posición preferida en el grupo, acechando a las presas por los laterales y después atacando, o bien moviéndose a una distancia más corta en el centro del grupo y atrapando a las presas que huyen de otras leonas.[87]\n\nLos machos de un grupo no suelen participar en la caza, excepto cuando se trata de presas grandes, como jirafas y búfalos. Los machos sin grupo se ven forzados a cazar en solitario, aunque también se han dado casos de machos que cazan en grupos.\n\nLas crías empiezan a presentar comportamiento de caza a la edad de unos tres meses, aunque no participan en la caza hasta que ya tienen casi un año. Empiezan a cazar de manera efectiva cuando se acercan a los dos años de edad.[88]\n\nReproducción y ciclo vital\n\nDurante el período de apareamiento, una pareja puede copular entre veinte y cuarenta veces al día durante unos cuantos días.\nLa mayoría de las leonas ya se han reproducido a los cuatro años de edad.[89] Los leones no se aparean en ninguna época particular del año y las hembras tienen numerosas fases de estro cada año.[90] Como en otros félidos, el pene del macho tiene unas espinas apuntando hacia atrás. Cuando se retira el pene, las espinas rozan las paredes de la vagina de la hembra, lo que puede causar la ovulación.[91] Una leona puede aparearse con más de un macho cuando está en celo;[92] durante el periodo de apareamiento, que puede durar varios días, se han observado leones copulando 157 veces en un periodo de 55 horas.[93] Se reproducen con mucha facilidad en cautividad.\n\nEl periodo de gestación dura una media de 110 días[90] (unos tres meses y medio) y la hembra da a luz a una camada de entre una y cuatro crías en una madriguera aislada, que puede encontrarse en zonas de matorrales, juncales, cuevas o alguna otra zona protegida, habitualmente separada del resto de la manada. Mientras las crías todavía están indefensas, la madre frecuentemente caza por sí sola, permaneciendo relativamente cerca de la madriguera donde se encuentran las crías.[94] Las crías nacen ciegas y no abren los ojos hasta aproximadamente una semana después de su nacimiento. Pesan entre 1200 y 2100 g al nacer y se encuentran prácticamente indefensas. Empiezan a arrastrarse al día o dos de nacer y a andar cuando ya tienen unas tres semanas.[95] La leona mueve las crías a un nuevo lugar numerosas veces al mes, llevándolas una por una cogidas por la piel de la nuca. Este movimiento tiene como objetivo impedir que se vaya acumulando su olor en el mismo lugar y así evitar la atención de posibles depredadores.[94]\n\nEn general, la madre se reintegra al grupo con sus crías cuando estas tienen entre nueve y diez semanas.[96] Sin embargo, a veces esta introducción a la vida en manada se produce antes, especialmente si otras leonas han dado a luz en la misma época. Por ejemplo, las leonas de un grupo suelen sincronizar su ciclo reproductivo con el fin de cooperar en la cría y el amamantamiento de los cachorros (una vez que estos han pasado la fase inicial de aislamiento con su madre), que maman indiscriminadamente de cualquiera de las hembras cuidadoras del grupo. Además de ofrecer una mayor protección, la sincronización de los nacimientos también es ventajosa en que, como los cachorros tienen un tamaño muy similar, tienen las mismas probabilidades de sobrevivir. Si una leona da a luz a una camada de cachorros un par de meses después de otra leona, por ejemplo, entonces las crías más jóvenes encuentran dificultades para alimentarse, ya que suelen ser dominadas por las mayores. Por lo tanto, la muerte de hambre es más común entre las crías jóvenes.\n\n\nEn primer plano, una leona preñada.\nAdemás de morirse de hambre, los cachorros también corren otros muchos peligros como, por ejemplo, ser cazados por chacales, hienas, leopardos, águilas marciales y serpientes. Incluso los búfalos, si perciben el olor de las crías del león, inician una estampida hacia la zona de matorral o la madriguera donde se encuentran los cachorros, haciendo todo lo posible por pisotear a las crías y darles muerte mientras mantienen a raya a la leona. Además, cuando uno o más machos nuevos desbancan al anterior macho asociado a la manada, frecuentemente matan a las crías existentes,[97] quizás porque las hembras no son fértiles y receptivas hasta que sus cachorros crecen o mueren. En total, hasta un 80 % de los cachorros mueren antes de llegar a los dos años de edad.[98]\n\nCuando se integran con el resto de la manada, los cachorros carecen de la confianza hacia cualquier otro adulto que no sea su madre. Aun así, pronto empiezan a participar en la vida del grupo, jugando entre ellos o intentando empezar a jugar con los adultos. Las leonas que tienen crías tienen más probabilidades de ser tolerantes hacia las de otras leonas que las que no tienen. La tolerancia de los machos hacia los cachorros varía: unas veces, el macho puede dejar pacientemente que las crías jueguen con su cola o su melena, mientras que otras puede gruñir y echar a los cachorros.[99]\n\n\nLa tolerancia de los machos hacia los cachorros varía. Pese a ello, es más probable que compartan comida con ellos que con las leonas.\nEl destete tiene lugar a los seis o siete meses de edad. Los machos logran la madurez a los tres años de edad y con cuatro o cinco años ya son capaces de desafiar y desbancar al macho adulto de otra manada. Empiezan a envejecer y debilitarse a más tardar entre los diez y quince años de edad,[100] si no han sido ya gravemente heridos defendiendo su manada. Por lo tanto, en cautiverio un león puede llegar a vivir treinta años; pero en su hábitat silvestre solo llega a vivir hasta los doce años los machos y dieciséis las hembras. Cuando el macho dominante es expulsado por su rival, raramente recupera su estatus dentro de la manada viéndose obligado a exiliarse. Cuanto antes empiecen a procrear, una vez toman el control de una manada, más éxito reproductivo tendrán antes de llegar a la vejez y ser desterrados por leones más jóvenes. Las leonas a menudo intentan defender fieramente a los cachorros ante un macho usurpador, pero raramente tienen éxito. El usurpador suele matar a todos los cachorros que tengan menos de dos años. Debido a que las hembras son más débiles y de menor peso con respecto a los machos, la defensa de las crías puede tener más probabilidades de éxito si tres o cuatro madres de una manada se unen contra un macho. Las hembras a las que el macho usurpador mató sus crías, entran en celo nuevamente en pocos días.[97]\n\nAl contrario de lo que dice la creencia popular, no solo los machos son expulsados de su manada pasando a ser nómadas, si bien es cierto que la mayoría de las hembras permanecen toda su vida en su manada natal. No obstante, cuando la manada se hace demasiado grande, la siguiente generación de crías de sexo femenino puede ser forzada a marcharse y buscar un territorio propio. Además, cuando un nuevo macho consigue el control de una manada, los ejemplares subadultos, tanto machos como hembras, pueden ser expulsados.[101] La vida de una hembra nómada es dura. Raramente consiguen que sus crías alcancen la madurez, ya que carecen de la protección de otros miembros de la manada.\n\nUn estudio científico encontró que tanto los machos como las hembras podrían mantener relaciones homosexuales.[102][103] Los machos forman parejas durante unos cuantos días y empiezan la actividad homosexual con cariñosas caricias con el hocico, que desembocan en coitos y empujones. Un estudio descubrió que aproximadamente un 8 % de las cópulas se producen entre dos machos. Se cree que las relaciones homosexuales entre hembras son bastante habituales en cautiverio, pero no se han observado en estado salvaje.\n\nSalud\nAunque los leones adultos no tienen depredadores naturales, los indicios sugieren que la mayoría sufren una muerte violenta causada por humanos o por otros leones.[104] Esto es particularmente cierto en el caso de los machos, que, como principales defensores de la manada, tienen más probabilidades de interactuar agresivamente con machos rivales. De hecho, pese a que un león macho puede lograr una edad de quince o dieciséis años si consigue no ser expulsado por otros machos, la mayoría de machos adultos no viven más de diez años. Este es el motivo por el cual en estado salvaje la longevidad media de los leones tiende a ser significativamente inferior a la de las leonas. Sin embargo, los miembros de ambos sexos pueden resultar heridos o incluso muertos por otros leones cuando entran en conflicto dos manadas con territorios concurrentes.\n\n\nUna leona subida a un árbol en el parque nacional Serengueti.\nCon respecto a los parásitos, se sabe que varias especies de garrapatas suelen infectar las orejas, el cuello y las ingles de la mayoría de los leones.[105][106] También, procedentes de intestinos de leones, se ha aislado la forma adulta de varias especies de tenias. Los leones contraen la solitaria al comer las formas larvarias presentes en la carne de antílope.[107]\n\nEn 1962, los leones del cráter de Ngorongoro fueron atacados por la mosca de los establos (Stomoxys calcitrans); esto hizo que los leones acabaran cubiertos de manchas calvas y ensangrentadas, al tiempo que completamente escuálidos. Los leones intentaron huir de las picaduras de las moscas sin éxito, subiendo a árboles o arrastrándose dentro de madrigueras de hienas; muchos de ellos murieron o emigraron y la población de leones del lugar se desplomó, pasando de setenta individuos a quince.[108] Un brote más reciente, en 2001, mató a seis leones.[109] Los leones, especialmente los que viven en cautividad, son vulnerables al virus del moquillo, al virus de inmunodeficiencia felina (VIF) y a la peritonitis infecciosa felina (PIF). El moquillo se transmite mediante los perros domésticos y otros carnívoros; un brote producido en 1994 en el parque nacional Serengueti provocó que muchos leones desarrollaran síntomas neurológicos, como por ejemplo convulsiones. Durante el brote, varios leones murieron de neumonía y encefalitis.[110] El VIF, que es similar al VIH, no afecta negativamente a los leones, pero su efecto sobre los gatos domésticos es lo suficientemente preocupante como para que el Species Survival Plan recomiende análisis sistemáticos a los leones en cautividad. Es muy frecuente y endémica en varias poblaciones de leones salvajes, pero es prácticamente inexistente entre los leones asiáticos y namibios.[48]\n\nComunicación\n\nFrotarse y lamerse son comportamientos sociales comunes en la manada.\nCuando están en reposo, los leones realizan actos sociales por medio de una serie de comportamientos y muestran movimientos expresivos muy desarrollados. Tienen un conjunto de expresiones faciales y posturas corporales que son gestos visuales.[111] Los gestos pacíficos más comunes son el de frotarse la cabeza y los lametones sociales,[112] que han sido comparados con el acicalamiento de los primates.[113] Frotarse la cabeza, utilizando el hocico para acariciar la frente, la cara y el cuello de otro león, parece ser una clase de saludo,[114] ya que se observa a menudo cuando un animal ha estado separado del resto o tras un combate o conflicto. Los machos tienden a frotar a otros machos, mientras que los cachorros y las hembras frotan a otras hembras.[115] Los lametones sociales suelen producirse en combinación con los rozamientos de cabeza; generalmente son mutuos y el receptor parece mostrar placer. La cabeza y el cuello son las partes del cuerpo que se lamen más habitualmente, cosa que podría ser por motivos prácticos, ya que un león no puede lamerse estas zonas por sí mismo.[116]\n\nSu repertorio de vocalizaciones también es amplio; las variaciones en la intensidad y la altura de los sonidos, en vez de las señales visuales, parecen formar la base de la comunicación. Los sonidos de los leones incluyen respingos, roncos, siseos, toses, maullidos, ladridos y, por supuesto, rugidos. Los leones tienden a rugir de manera muy característica, empezando con unos cuantos rugidos graves y largos, que conducen a una serie de rugidos más cortos. Suelen rugir por la noche; el sonido, que puede ser escuchado desde una distancia de 10 km, sirve para anunciar la presencia del animal. Un león es capaz, con sólo escuchar una vez el rugido de otros leones, de dirigirse al punto exacto de su procedencia en distancias de hasta al menos 5 km. Sin importar que estén ocultos entre la maleza y en silencio; si han permanecido inmóviles en el mismo lugar, los encontrará.[117] Los leones tienen el rugido más potente de entre los félidos.\n\nRelaciones interespecíficas de depredación\n\nUna hiena manchada en la Zona de conservación de Ngorongoro. Las hienas son las principales competidoras de los leones.\nLa relación entre los leones y las hienas manchadas en las áreas donde coexisten es única por su complejidad e intensidad. Ambas especies son superpredadores que se alimentan de las mismas presas, de forma que compiten directamente entre ellas. Frecuentemente luchan entre sí y se roban la caza. Aunque la concepción popular ve las hienas como carroñeras oportunistas que se aprovechan de las habilidades cazadoras de los leones, a menudo se da el caso contrario. En el cráter de Ngorongoro de Tanzania, la población de hienas manchadas supera ampliamente la de leones, que obtienen una parte importante de su comida robando las presas de las hienas. Sin embargo, el conflicto entre las dos especies va más allá de los combates por el alimento. Entre los animales, los límites territoriales con otras especies son usualmente ignorados. Las hienas y los leones son una excepción; marcan límites entre ellos igual que lo harían con miembros de su propia especie. Los leones machos en concreto son extremadamente agresivos con las hienas y han sido observados cazando y matando hienas sin comérselas. A su vez, las hienas son uno de los principales depredadores de cachorros de león y sitian a las leonas para robarles sus crías.[118][119]\n\nLos leones tienden a dominar a félidos más pequeños como guepardos y leopardos en las áreas donde son simpátricos. Les roban las presas, matan a sus cachorros e incluso a los adultos cuando tienen oportunidad. El guepardo tiene un 50 % de posibilidades de perder su caza ante los leones u otros depredadores.[120] Los leones representan un gran peligro para los cachorros del guepardo y hasta un 90 % de los cachorros mueren durante las primeras semanas de vida a causa de ataques por parte de otros depredadores. Los guepardos evitan la competencia cazando en diferentes momentos del día y esconden a sus cachorros en zonas de hierba densa. Los leopardos también utilizan estas tácticas, pero tienen la ventaja de poder sobrevivir comiendo presas más pequeñas, algo que no pueden hacer los leones o los guepardos. Además, a diferencia de los guepardos, los leopardos pueden escalar árboles y utilizarlos para mantener a sus crías y su caza a salvo de los leones. No obstante, en ocasiones las leonas consiguen subir al árbol para robar la comida del leopardo.[121] De manera similar, los leones dominan a los licaones, no solo robándoles la caza, sino también cazando licaones.\n\nOtro depredador simpátrico que puede amenazar al león es el cocodrilo del Nilo. Según el tamaño del cocodrilo y del león, cualquiera de los dos puede perder presas o carroña frente al otro. Se conocen casos de leones que han matado cocodrilos que se habían adentrado en tierra[122] y viceversa cuando es el león quien entra en las aguas donde viven estos reptiles, como lo demuestra el hecho de que en alguna ocasión se han descubierto zarpas de león en el estómago de los cocodrilos.[123] En ocasiones, varios adultos de una manada de leones dan caza a cocodrilos de considerable tamaño que se adentran en tierra o se encuentran en aguas poco profundas, pero probablemente los cocodrilos mayores a 4 metros no tengan ningún predador debido a su gran tamaño y fuerza.\n\nEvolución\n\nCráneo de Panthera leo spelaea del Pleistoceno de Francia.\nEl fósil más antiguo conocido similar a un león proviene de Laetoli (Tanzania) y podría tener una antigüedad de 3,5 millones de años; algunos científicos han identificado estos restos como pertenecientes a Panthera leo, pero no está confirmado y lo más que se puede decir es que pertenecen a un félido similar a Panthera. Los restos más antiguos confirmados de Panthera fueron descubiertos en 2010 en el Tíbet y clasificados en 2013 como Panthera blytheae, poseen una antigüedad de 4,1 a 5,9 millones de años. La importancia de estos fósiles radica en el hecho de que refuerzan la teoría que establece que los félidos pertenecientes a la subfamilia Pantherinae se originaron en Asia central y no en África.[124][125] Los parientes más cercanos del león son las otras especies del género Panthera: el tigre, el jaguar y el leopardo. Estudios morfológicos y genéticos revelan que el tigre fue la primera especie en divergir del resto. Hace unos 1,9 millones de años, el jaguar se separó del grupo restante, que contenía a los antepasados de leopardos y leones. Posteriormente, el león y el leopardo se separaron hace entre 1,25 y 1 millones de años.[126]\n\nPanthera leo evolucionó en África entre hace un millón y ochocientos mil años antes de dispersarse por la región holártica.[127] Apareció por primera vez en Europa hace 700 000 años con la subespecie Panthera leo fossilis, encontrada en Isernia (Italia). Este león evolucionó al posterior león de las cavernas (Panthera leo spelaea), que apareció hace unos trescientos mil años. Durante el Pleistoceno superior, el león se extendió por América, donde evolucionó como Panthera leo atrox, el león americano.[128] Los leones se extinguieron del norte de Eurasia y América a finales de la última glaciación, hace unos diez mil años;[129] pudiendo haber sido víctimas de la extinción de la megafauna del Pleistoceno.[130]\n\nSubespecies\n\nLeón de Katanga (Panthera leo bleyenberghi).\nUn estudio genético efectuado por científicos de la Universidad de Durhan concluyó que el último ancestro común de todas las subespecies modernas de león vivió en África hace unos ciento veinticuatro mil años. Antes de esa época, en el Pleistoceno Medio, los leones se distribuían por todo el continente africano. En ese momento, durante el periodo húmedo denominado MIS5 que favoreció el gran desarrollo de la selva desde el golfo de Guinea hasta el Rift, las poblaciones del norte y oeste se separaron de las del sur y este. Más tarde, hace cerca de cincuenta y un mil años el clima africano se hizo cada vez más seco por lo que se formaron barreras como el desierto del Sahara que separó a los leones del oeste y norte de África. Mientras las selvas ecuatoriales se contraían, las poblaciones del oeste se expandían hacia el centro. A la vez, existía una complicada interacción entre las poblaciones del sur y este con el Valle del Rift como barrera parcial a la dispersión. El mismo estudio indicó que estos animales salieron de África hace aproximadamente veintiún mil años, final del Pleistoceno, llegando hasta la India, y posteriormente, hace unos cinco mil años —ya en el Holoceno— otra oleada salió del norte de África llegando hasta lo que hoy en día es Irán y el Medio Oriente. Sin embargo, en el Medio Oriente se han encontrado restos fósiles de leones que datan de todo el Pleistoceno Superior, por lo que debieron llegar allí anteriormente, pero su rastro genético ha sido superpuesto por esta otra oleada más reciente.[131][132]\n\nTradicionalmente se reconocían doce subespecies modernas de león, de las que la más grande era el león del Atlas.[133] Las diferencias principales entre estas subespecies son la distribución geográfica, la apariencia de la melena y el tamaño. Como estas características son poco consistentes y muy variables, la mayoría de estas formas son discutibles y probablemente no sean válidas; además, a menudo las distinciones se basaban en material de zoológicos de origen desconocido que podría haber tenido características morfológicas «sorprendentes, pero anormales».[48] Actualmente es habitual que solo se reconozcan ocho subespecies,[42][129] pero una de ellas (el león del Cabo, antiguamente descrita como Panthera leo melanochaitus) es probablemente inválida.[42]\n\nIncluso las siete subespecies restantes podrían ser demasiadas; la variación mitocondrial reciente entre los leones africanos es escasa, lo que sugiere que todos los leones subsaharianos podrían ser considerados una única subespecie, posiblemente dividida en dos clados principales: uno al oeste del Gran Valle del Rift y el otro al este. Los leones de Tsavo, al este de Kenia, están mucho más próximos genéticamente hablando a los leones de Transvaal (Sudáfrica) que a los de los montes Aberdare del este de Kenia.[134][135] Las razas massaica, somaliensis y rosevelti se incluyen en nubica. La raza nominal leo del noroeste de África y la raza melanochaitus de la región de El Cabo (Sudáfrica) se han extinguido. Así pues, se reconocen seis subespecies en la actualidad:[93]\n\nEn 2017 un equipo de investigadores pertenecientes a la UICN publicó una nueva clasificación taxonómica de la familia felidae en la que solo reconocían dos subespecies de león: Panthera leo leo que agrupa al león asiático, al de África occidental, central y a las ya desaparecidas poblaciones del león del Atlas y Panthera leo melanochaita que agrupa a los leones del África oriental y meridional.[136]\n'}
SOFT = []

def main(root: Path = ROOT) -> int:
    stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S-%f")
    bk = root / ".parche_backups" / stamp
    texts, changed = {}, set()
    for rel, old, new, marca in ALL_EDITS:                              # comprobar TODO antes de escribir nada
        p = root / rel
        if not p.is_file():
            print(f"FALTA {rel}: no se toca nada."); return 1
        txt = texts[rel] if rel in texts else p.read_text(encoding="utf-8")
        if marca in txt:
            texts[rel] = txt; continue
        if txt.count(old) != 1:
            print(f"ERROR {rel}: un trozo a cambiar aparece {txt.count(old)} veces (debe ser 1): {old[:70]!r}. No se toca nada."); return 1
        texts[rel] = txt.replace(old, new); changed.add(rel)
    plan = [(root / rel, rel, texts[rel]) for rel in sorted(changed)]
    for rel, content in NEW_FILES.items():
        p = root / rel
        if not p.exists() or p.read_text(encoding="utf-8") != content:
            plan.append((p, rel, content))
    for p, rel, txt in plan:
        if p.exists():
            (bk / rel).parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(p, bk / rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(txt, encoding="utf-8")
        if rel.endswith(".py"):
            py_compile.compile(str(p), doraise=True)
        print(f"  escrito {rel}")


    for rel, marca, bloque, antes in SOFT:                              # documentacion: tolerante, nunca bloquea
        p = root / rel
        try:
            t = p.read_text(encoding="utf-8") if p.exists() else ""
            if marca in t:
                continue
            if antes and antes in t:
                t = t.replace(antes, bloque + antes, 1)
            else:
                t = t + ("" if t.endswith("\n") or not t else "\n") + bloque
            if p.exists():
                (bk / rel).parent.mkdir(parents=True, exist_ok=True); shutil.copy2(p, bk / rel)
            p.write_text(t, encoding="utf-8"); print(f"  actualizado {rel}")
        except Exception as e:
            print(f"  (aviso) no se pudo actualizar {rel}: {e!r}")
    print(f"parche-114 instalado. Copias en {bk}" if plan else "parche-114: nada que hacer.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

